const o={id:"appendix-grammar",type:"appendix",order:4},r=[{type:"title",en:["Grammar Patterns Reference"],zh:["语法结构参考"],ru:["Справочник грамматических конструкций"]},{type:"summary",en:["Every pattern from the 26 lessons, in one place, in lesson order."],zh:[],ru:["Все грамматические схемы из 26 уроков в одном месте, по порядку уроков."]},{type:"prose",en:["Each box below holds one lesson's patterns, and its title says which lesson.","Use this page to look up a pattern, then go back to its lesson for examples and practice."],zh:[],ru:["В каждом блоке ниже — схемы одного урока, и заголовок говорит, какого.","Найдите здесь нужную схему, а потом вернитесь к её уроку за примерами и упражнениями."],tldr:{en:["Every pattern from the lessons, in lesson order."],zh:[],ru:["Все грамматические схемы из уроков, по порядку."]},necessity:{en:["You can look up a pattern without hunting through the lessons."],zh:[],ru:["Схему можно найти, не листая все уроки."]}},{type:"info",subtype:"grammar",title:{en:["Lesson 1 · Sounds and Symbols"],zh:[],ru:["Урок 1 · Звуки и знаки"]},items:[{text:{en:['**word-word / "name or sound"** — a hyphen joins words into one / quotes mark a name or a sound. How a word shows in writing: the syllables of one word stay together (dòng-wù), a hyphen glues a small word to another so they work as one word (zhè-ge, hěn-dà-de), and quotes mark a name or a sound ("wāng-wāng").'],ru:['**word-word / "name or sound"** — Как слово выглядит на письме: слоги одного слова стоят вместе (dòng-wù), дефис приклеивает маленькое слово к другому, и вместе они работают как одно слово (zhè-ge, hěn-dà-de), а кавычки отмечают имя или звук ("wāng-wāng").'],zh:[]},items:[{text:{en:['{{Word:ta1}} {{word:jiao4}} "wāng-wāng". (It barks "woof-woof".)'],ru:['{{Word:ta1}} {{word:jiao4}} "wāng-wāng".'],zh:[]}},{text:{en:['{{Word:zhe4}}-{{light:ge4}} {{word:shi4}} "Beijing". (This is "Beijing".)'],ru:['{{Word:zhe4}}-{{light:ge4}} {{word:shi4}} "Beijing".'],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 2 · Words and Sentences"],zh:[],ru:["Урок 2 · Слова и предложения"]},items:[{text:{en:["**A {{word:shi4}} B** — A is B. Says that one thing is another: shì goes between the two."],ru:["**A {{word:shi4}} B** — Говорит, что одно есть другое: shì стоит между ними."],zh:[]},items:[{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:ren2}}. (This is a person.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:shi4}} {{word:hao3}}-{{word:de}} {{word:ren2}}. (I am a good person.)"],ru:["{{Word:wo3}} {{word:shi4}} {{word:hao3}}-{{word:de}} {{word:ren2}}."],zh:[]}}]},{text:{en:["**Subject + Predicate** — Who or what, then what is said about it. A sentence names someone or something, then says something about it."],ru:["**Subject + Predicate** — Предложение называет кого-то или что-то и говорит об этом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:shi4}} {{word:ren2}}. (I am a person.)"],ru:["{{Word:wo3}} {{word:shi4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:zhe4}}. (This.)"],ru:["{{Word:zhe4}}."],zh:[]}}]},{text:{en:["**A {{word:bu4}} {{word:shi4}} B** — A is not B. Bù before shì says one thing is not another: dòng-wù bù shì zhíwù, an animal is not a plant."],ru:["**A {{word:bu4}} {{word:shi4}} B** — Bù перед shì говорит, что одно не есть другое: dòng-wù bù shì zhíwù — животное не растение."],zh:[]},items:[{text:{en:["{{Word:dong4}}-{{word:wu4}} {{word:bu4}} {{word:shi4}} {{word:zhi2wu4}}. (An animal is not a plant.)"],ru:["{{Word:dong4}}-{{word:wu4}} {{word:bu4}} {{word:shi4}} {{word:zhi2wu4}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:bu4}} {{word:shi4}} {{word:ren2}}. (This is not a person.)"],ru:["{{Word:zhe4}} {{word:bu4}} {{word:shi4}} {{word:ren2}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 3 · Modifying Nouns"],zh:[],ru:["Урок 3 · Описание существительных"]},items:[{text:{en:["**Subject {{word:hen3}} adjective** — Subject is (very) adjective. Says what something is like: hěn goes before the describing word."],ru:["**Subject {{word:hen3}} adjective** — Говорит, каково что-то: hěn стоит перед описывающим словом."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:hen3}} {{word:hao3}}. (The water is good.)"],ru:["{{Word:shui3}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:di4}}-{{light:fang1}} {{word:hen3}} {{word:da4}}. (The place is big.)"],ru:["{{Word:di4}}-{{light:fang1}} {{word:hen3}} {{word:da4}}."],zh:[]}}]},{text:{en:["**describing word + noun** — The noun that is so. A describing word right before a noun, with no de, goes with it: lǎo nǚ-rén, an old woman; dà huài dòng-wù, a big bad animal; bié rén, other people."],ru:["**describing word + noun** — Описание прямо перед существительным, без de, относится к нему: lǎo nǚ-rén — старая женщина; dà huài dòng-wù — большой злой зверь; bié rén — другие люди."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:you3}} {{word:yi1}}-{{light:ge4}} {{word:hao3}} {{word:ren2}}. (I have a good person.)"],ru:["{{Word:wo3}} {{word:you3}} {{word:yi1}}-{{light:ge4}} {{word:hao3}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:da4}} {{word:huai4}} {{word:dong4}}-{{word:wu4}} {{word:lai2}} {{word:le}}. (The big bad animal came.)"],ru:["{{Word:da4}} {{word:huai4}} {{word:dong4}}-{{word:wu4}} {{word:lai2}} {{word:le}}."],zh:[]}}]},{text:{en:["**noun + describing word ({{word:de}}) + noun** — The noun that is so. A noun and a describing word, with no hěn, can describe a place or a thing before de: rén shǎo, zhíwù duō de dì-fāng, a place with few people and many plants; or follow an order: chī shuǐ-guǒ, shēntǐ hǎo."],ru:["**noun + describing word ({{word:de}}) + noun** — Существительное и описание без hěn могут описывать место или вещь перед de: rén shǎo, zhíwù duō de dì-fāng — место, где мало людей и много растений; или идти после приказа: chī shuǐ-guǒ, shēntǐ hǎo."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:ren2}} {{word:shao3}}, {{word:zhi2wu4}} {{word:duo1}} {{word:de}} {{word:di4}}-{{word:fang1}}. (I love the countryside.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:ren2}} {{word:shao3}}, {{word:zhi2wu4}} {{word:duo1}} {{word:de}} {{word:di4}}-{{word:fang1}}."],zh:[]}},{text:{en:["{{Word:chi1}} {{word:shui3}}-{{word:guo3}}, {{word:shen1ti3}} {{word:hao3}}. (Eat fruit and stay healthy.)"],ru:["{{Word:chi1}} {{word:shui3}}-{{word:guo3}}, {{word:shen1ti3}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**modifier-{{word:de}} noun** — the modifier's noun. A describing word, or an owner, goes before the noun and takes -de."],ru:["**modifier-{{word:de}} noun** — Описывающее слово или владелец стоит перед существительным и получает -de."],zh:[]},items:[{text:{en:["{{Word:da4}}-{{word:de}} {{word:di4}}-{{light:fang1}}. (A big place.)"],ru:["{{Word:da4}}-{{word:de}} {{word:di4}}-{{light:fang1}}."],zh:[]}},{text:{en:["{{Word:wo3}}-{{word:de}} {{word:jia1}}. (My home.)"],ru:["{{Word:wo3}}-{{word:de}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:wo3}}-{{word:de}}. (This is mine.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:wo3}}-{{word:de}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:bao1}} {{word:shi4}} {{word:kong1}}-{{word:de}}. (This bag is empty.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:bao1}} {{word:shi4}} {{word:kong1}}-{{word:de}}."],zh:[]}}]},{text:{en:["**{{word:hao3}} / {{word:nan2}} + verb** — Good or hard to do. Hǎo or nán before a verb says it is good or hard to do: hǎo wánr, fun to play; nán zuò, hard to do."],ru:["**{{word:hao3}} / {{word:nan2}} + verb** — Hǎo или nán перед глаголом говорит, что это хорошо или трудно делать: hǎo wánr — интересно играть; nán zuò — трудно делать."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:hao3}} {{word:wan2r}}. (This is interesting.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:hao3}} {{word:wan2r}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:nan2}} {{word:zuo4}}. (This is hard to do.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:nan2}} {{word:zuo4}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 4 · Pointing at People and Things"],zh:[],ru:["Урок 4 · Указываем на людей и вещи"]},items:[{text:{en:["**{{word:zhe4}} / {{word:na4}} / number + measure word (+ noun)** — this / that / a number + counting word (+ noun). A counting word goes after zhè, nà or a number: zhè-ge (this one), zhè-ge rén (this person), liǎng-ge rén (two people)."],ru:["**{{word:zhe4}} / {{word:na4}} / number + measure word (+ noun)** — Счётное слово ставится после zhè, nà или числа: zhè-ge («вот этот»), zhè-ge rén («этот человек»), liǎng-ge rén («два человека»)."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:shi4}} {{word:dong4}}-{{word:wu4}}. (This one is an animal.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:shi4}} {{word:dong4}}-{{word:wu4}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:ren2}}. (This person.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:na4}}-{{word:xie1}} {{word:ren2}} {{word:hen3}} {{word:hao3}}. (Those people are good.)"],ru:["{{Word:na4}}-{{word:xie1}} {{word:ren2}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:liang3}}-{{light:ge4}} {{word:ren2}}. (Two people.)"],ru:["{{Word:liang3}}-{{light:ge4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:liang3}}-{{light:ge4}} {{word:ren2}} {{word:hen3}} {{word:hao3}}. (These two people are good.)"],ru:["{{Word:zhe4}} {{word:liang3}}-{{light:ge4}} {{word:ren2}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:yao4}} {{word:na4}}-{{word:zhong3}} {{word:chang2}}-{{word:de}} {{word:dong1xi}}. (I want that kind of long thing.)"],ru:["{{Word:wo3}} {{word:yao4}} {{word:na4}}-{{word:zhong3}} {{word:chang2}}-{{word:de}} {{word:dong1xi}}."],zh:[]}}]},{text:{en:["**noun + {{word:men}}** — The people of that kind. Men after a noun means more than one person: háizi-men, the children. After wǒ, nǐ or tā it makes we, you all or they; a number and a counting word can follow: wǒ-men sān-ge rén, the three of us."],ru:["**noun + {{word:men}}** — Men после существительного делает множественное число для людей: háizi-men — дети. После wǒ, nǐ, tā оно даёт «мы», «вы», «они»; дальше могут идти число и счётное слово: wǒ-men sān-ge rén — нас трое."],zh:[]},items:[{text:{en:["{{Word:hai2zi}}-{{word:men}} {{word:zai4}} {{word:xue2}}-{{word:xiao4}}. (The children are at school.)"],ru:["{{Word:hai2zi}}-{{word:men}} {{word:zai4}} {{word:xue2}}-{{word:xiao4}}."],zh:[]}},{text:{en:["{{Word:wo3}}-{{word:men}} {{word:san1}}-{{light:ge4}} {{word:ren2}} {{word:yi4qi3}} {{word:qu4}}. (The three of us go together.)"],ru:["{{Word:wo3}}-{{word:men}} {{word:san1}}-{{light:ge4}} {{word:ren2}} {{word:yi4qi3}} {{word:qu4}}."],zh:[]}}]},{text:{en:["**modifier-{{word:de}} modifier-{{word:de}} noun** — the first modifier's second modifier's noun. Modifiers stack up before one noun, each with its own -de."],ru:["**modifier-{{word:de}} modifier-{{word:de}} noun** — Несколько определений стоят подряд перед одним существительным, у каждого свой -de."],zh:[]},items:[{text:{en:["{{Word:wo3}}-{{word:de}} {{word:hao3}}-{{word:de}} {{word:ren2}}. (My good person.)"],ru:["{{Word:wo3}}-{{word:de}} {{word:hao3}}-{{word:de}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:ni3}}-{{word:de}} {{word:da4}}-{{word:de}} {{word:jia1}}. (This is your big home.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:ni3}}-{{word:de}} {{word:da4}}-{{word:de}} {{word:jia1}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 5 · Verbs 1 — Who does what"],zh:[],ru:["Урок 5 · Глаголы 1 — Кто что делает"]},items:[{text:{en:["**Subject + verb + Object** — Subject does the verb to the object. Who does what to what: the doer, then the action, then what it is done to."],ru:["**Subject + verb + Object** — Кто что делает: сначала тот, кто делает, потом действие, потом то, на что оно направлено."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:ni3}}. (I love you.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:ni3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:xiao4}}. (He laughs.)"],ru:["{{Word:ta1}} {{word:xiao4}}."],zh:[]}}]},{text:{en:["**Subject {{word:bu4}} verb** — Subject does not do the verb. Says no: bù goes before the verb, shì or the describing word."],ru:["**Subject {{word:bu4}} verb** — Говорит «нет»: bù стоит перед глаголом, shì или описывающим словом."],zh:[]},items:[{text:{en:["{{Word:zhe4}} {{word:bu4}} {{word:shi4}} {{word:ren2}}. (This is not a person.)"],ru:["{{Word:zhe4}} {{word:bu4}} {{word:shi4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:bu4}} {{word:ai4}} {{word:ni3}}. (I do not love you.)"],ru:["{{Word:wo3}} {{word:bu4}} {{word:ai4}} {{word:ni3}}."],zh:[]}},{text:{en:["{{Word:shui3}} {{word:bu4}} {{word:hen3}} {{word:hao3}}. (The water is not very good.)"],ru:["{{Word:shui3}} {{word:bu4}} {{word:hen3}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**Who + {{word:ting1}} / {{word:kan4}} + who + verb** — Who hears / sees someone do the verb. Says you hear or see someone do something: tīng or kàn, then who, then what they do."],ru:["**Who + {{word:ting1}} / {{word:kan4}} + who + verb** — Говорит, что вы слышите или видите, как кто-то что-то делает: tīng или kàn, потом кто, потом что он делает."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}. (I hear you speak.)"],ru:["{{Word:wo3}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}. (I love listening to you talk.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}."],zh:[]}}]},{text:{en:["**Who + {{word:mei2}}-{{word:you3}} + thing** — Who doesn't have the thing. Méi-yǒu says someone doesn't have a thing: wǒ méi-yǒu jīn, I don't have money. Yǒu is have; méi-yǒu is don't have."],ru:["**Who + {{word:mei2}}-{{word:you3}} + thing** — Méi-yǒu говорит, что у кого-то чего-то нет: wǒ méi-yǒu jīn — у меня нет денег. Yǒu — «иметь», méi-yǒu — «не иметь»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:mei2}}-{{word:you3}} {{word:jin1}}. (I don't have money.)"],ru:["{{Word:wo3}} {{word:mei2}}-{{word:you3}} {{word:jin1}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:mei2}}-{{word:you3}} {{word:shui3}}. (He doesn't have water.)"],ru:["{{Word:ta1}} {{word:mei2}}-{{word:you3}} {{word:shui3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 6 · Questions and Answers"],zh:[],ru:["Урок 6 · Вопросы и ответы"]},items:[{text:{en:["**sentence {{word:ma}}** — Is it so? Asks a yes-or-no question: ma goes at the end of the sentence."],ru:["**sentence {{word:ma}}** — Задаёт вопрос «да или нет»: ma стоит в конце предложения."],zh:[]},items:[{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:ren2}} {{word:ma}}? (Is this a person?)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:ren2}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:shui3}} {{word:hen3}} {{word:hao3}} {{word:ma}}? (Is the water good?)"],ru:["{{Word:shui3}} {{word:hen3}} {{word:hao3}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:gong1}}-{{word:ju4}} {{word:xiao3}} {{word:ma}}? (Is the tool small?)"],ru:["{{Word:gong1}}-{{word:ju4}} {{word:xiao3}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**verb phrase / describing word + {{word:ma}}?** — Is it so? A short yes-or-no question: yǒu … ma, do you have …; yuǎn ma, is it far."],ru:["**verb phrase / describing word + {{word:ma}}?** — Короткий вопрос «да или нет»: yǒu … ma — есть ли …; yuǎn ma — далеко ли."],zh:[]},items:[{text:{en:["{{Word:yuan3}} {{word:ma}}? (Is it far?)"],ru:["{{Word:yuan3}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:you3}} {{word:bie2}} {{word:de}} {{word:yan2se4}} {{word:ma}}? (Do you have another color?)"],ru:["{{Word:you3}} {{word:bie2}} {{word:de}} {{word:yan2se4}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Subject verb-{{word:bu4}}-verb?** — Does the subject do the verb or not? Asks a yes-or-no question another way: the verb, bù, and the verb again."],ru:["**Subject verb-{{word:bu4}}-verb?** — Ещё один способ спросить «да или нет»: глагол, bù и тот же глагол ещё раз."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:ting1}}-{{word:bu4}}-{{word:ting1}}? (Do you listen?)"],ru:["{{Word:ni3}} {{word:ting1}}-{{word:bu4}}-{{word:ting1}}?"],zh:[]}},{text:{en:["{{Word:ta1}} {{word:you3}}-{{word:mei2}}-{{word:you3}} {{word:jin1}}? (Does she have money?)"],ru:["{{Word:ta1}} {{word:you3}}-{{word:mei2}}-{{word:you3}} {{word:jin1}}?"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:ting1}}-{{word:bu4}}-{{word:ting1}} {{word:ba4ba}}-{{word:ma1ma}}? (Do you listen to your parents?)"],ru:["{{Word:ni3}} {{word:ting1}}-{{word:bu4}}-{{word:ting1}} {{word:ba4ba}}-{{word:ma1ma}}?"],zh:[]}}]},{text:{en:["**{{word:duo1}} + describing word? / {{word:duo1}}-{{word:shao3}}?** — How big / how many? Duō before a describing word asks how much: nǐ duō dà, how old are you; duō rè, how hot. Duō-shǎo asks how many or how much."],ru:["**{{word:duo1}} + describing word? / {{word:duo1}}-{{word:shao3}}?** — Duō перед описанием спрашивает «насколько»: nǐ duō dà — сколько тебе лет; duō rè — насколько жарко. Duō-shǎo спрашивает «сколько»."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:duo1}} {{word:da4}}? (How old are you?)"],ru:["{{Word:ni3}} {{word:duo1}} {{word:da4}}?"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:you3}} {{word:duo1}}-{{word:shao3}} {{word:ge4}}? (How many do you have?)"],ru:["{{Word:ni3}} {{word:you3}} {{word:duo1}}-{{word:shao3}} {{word:ge4}}?"],zh:[]}},{text:{en:["{{Word:qu4}} {{word:na4}}-{{word:li3}} {{word:duo1}}-{{word:shao3}} {{word:jin1}}? (How much is it to go there?)"],ru:["{{Word:qu4}} {{word:na4}}-{{word:li3}} {{word:duo1}}-{{word:shao3}} {{word:jin1}}?"],zh:[]}}]},{text:{en:['**Who + verb + {{word:shen2me}}?** — Who does the verb to what? Asks "what?": shénme goes where the answer would go. Before a noun it asks which kind.'],ru:["**Who + verb + {{word:shen2me}}?** — Спрашивает «что?»: shénme стоит там, где был бы ответ. Перед существительным оно спрашивает, какой именно."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:you3}} {{word:shen2me}} {{word:gong1}}-{{word:ju4}}? (What tools do you have?)"],ru:["{{Word:ni3}} {{word:you3}} {{word:shen2me}} {{word:gong1}}-{{word:ju4}}?"],zh:[]}},{text:{en:["{{Word:ta1}} {{word:mai3}} {{word:shen2me}} {{word:gong1}}-{{word:ju4}}? (What tool does he buy?)"],ru:["{{Word:ta1}} {{word:mai3}} {{word:shen2me}} {{word:gong1}}-{{word:ju4}}?"],zh:[]}}]},{text:{en:["**{{word:na3}} + (counting word) + noun?** — Which one? Nǎ asks which: nǎ-ge rén, which person; nǎ guó rén, from which country; nǎ tiān, which day."],ru:["**{{word:na3}} + (counting word) + noun?** — Nǎ спрашивает «который»: nǎ-ge rén — какой человек; nǎ guó rén — из какой страны; nǎ tiān — какой день."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:ai4}} {{word:na3}} {{word:yi1}} {{word:ge4}}? (Which one do you love?)"],ru:["{{Word:ni3}} {{word:ai4}} {{word:na3}} {{word:yi1}} {{word:ge4}}?"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:shi4}} {{word:na3}} {{word:guo2}} {{word:ren2}}? (Which country are you from?)"],ru:["{{Word:ni3}} {{word:shi4}} {{word:na3}} {{word:guo2}} {{word:ren2}}?"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:de}} {{word:sheng1}}-{{word:ri4}} {{word:shi4}} {{word:na3}} {{word:tian1}}? (When is your birthday?)"],ru:["{{Word:ni3}} {{word:de}} {{word:sheng1}}-{{word:ri4}} {{word:shi4}} {{word:na3}} {{word:tian1}}?"],zh:[]}}]},{text:{en:["**Thing + {{word:zen3me}} {{word:yang4}}?** — How is it? Zěnme-yàng asks how it is: jīn-tiān zěnme yàng, how is today."],ru:["**Thing + {{word:zen3me}} {{word:yang4}}?** — Zěnme-yàng спрашивает «как»: jīn-tiān zěnme yàng — как сегодня."],zh:[]},items:[{text:{en:["{{Word:jin1}}-{{word:tian1}} {{word:zen3me}} {{word:yang4}}? (How is today?)"],ru:["{{Word:jin1}}-{{word:tian1}} {{word:zen3me}} {{word:yang4}}?"],zh:[]}}]},{text:{en:['**Who + {{word:wei4}}-{{word:shen2me}} / {{word:zen3me}} + verb?** — Why / how does who do it? Asks "why?" or "how?": wèi-shénme or zěnme goes before the verb, and wèi-shénme also goes before bù.'],ru:["**Who + {{word:wei4}}-{{word:shen2me}} / {{word:zen3me}} + verb?** — Спрашивает «почему?» или «как?»: wèi-shénme или zěnme стоит перед глаголом, а wèi-shénme ещё и перед bù."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:wei4}}-{{word:shen2me}} {{word:bu4}} {{word:chi1}}? (Why don't you eat?)"],ru:["{{Word:ni3}} {{word:wei4}}-{{word:shen2me}} {{word:bu4}} {{word:chi1}}?"],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:zen3me}} {{word:xie3}}? (How do you write this?)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:zen3me}} {{word:xie3}}?"],zh:[]}}]},{text:{en:["**Topic + sentence** — As for the topic: the sentence. A thing can come first as the topic, then a whole sentence about it: wǒ bàba shēntǐ hěn hǎo, as for my dad, his body is fine; shénme wǒ dōu yào, whatever it is, I want it."],ru:["**Topic + sentence** — Вещь может стоять первой как тема, а затем целое предложение о ней: wǒ bàba shēntǐ hěn hǎo — что до моего папы, у него здоровье хорошее; shénme wǒ dōu yào — что бы это ни было, я хочу."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ba4ba}} {{word:shen1ti3}} {{word:hen3}} {{word:hao3}}. (My dad is healthy.)"],ru:["{{Word:wo3}} {{word:ba4ba}} {{word:shen1ti3}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:shen2me}} {{word:wo3}} {{word:dou1}} {{word:yao4}}. (No matter what, I want it.)"],ru:["{{Word:shen2me}} {{word:wo3}} {{word:dou1}} {{word:yao4}}."],zh:[]}}]},{text:{en:["**verb. / {{word:bu4}} + verb.** — Yes. / No. An answer can be only what is said: the verb for yes, bù and the verb for no. A sentence can leave the doer out. Shì and bù shì answer alone too, with no complement: yes, it is / no, it isn't."],ru:["**verb. / {{word:bu4}} + verb.** — Ответ может быть только тем, что говорится: глагол — «да», bù и глагол — «нет». В предложении можно не называть того, кто делает. Shì и bù shì тоже отвечают одни, без дополнения: да, это так / нет, не так."],zh:[]},items:[{text:{en:["{{Word:ting1}}. (Yes, I do.)"],ru:["{{Word:ting1}}."],zh:[]}},{text:{en:["{{Word:bu4}} {{word:ting1}}. (No, I don't.)"],ru:["{{Word:bu4}} {{word:ting1}}."],zh:[]}},{text:{en:["{{Word:mei2}}-{{word:you3}} {{word:wen4}}-{{word:ti2}}. (No problem.)"],ru:["{{Word:mei2}}-{{word:you3}} {{word:wen4}}-{{word:ti2}}."],zh:[]}},{text:{en:["{{Word:shi4}}. (Yes, it is.)"],ru:["{{Word:shi4}}."],zh:[]}},{text:{en:["{{Word:bu4}} {{word:shi4}}. (No, it isn't.)"],ru:["{{Word:bu4}} {{word:shi4}}."],zh:[]}}]},{text:{en:["**{{word:shuo1}} {{word:bu4}}** — Say no. Shuō bù says no, as an answer or an objection: tā shuō bù, he says no."],ru:["**{{word:shuo1}} {{word:bu4}}** — Shuō bù значит «сказать нет»: tā shuō bù — он говорит «нет»."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:shuo1}} {{word:bu4}}. (He says no.)"],ru:["{{Word:ta1}} {{word:shuo1}} {{word:bu4}}."],zh:[]}}]},{text:{en:["**Who + verb: what was said** — Who said: the words. After shuō, wèn, xiào and other verbs of saying, a colon brings in what was said: tā shuō: nǐ hǎo. What was said runs to the end of the sentence, so its ma or le stays inside it."],ru:["**Who + verb: what was said** — После shuō, wèn, xiào и других глаголов речи двоеточие вводит сказанное: tā shuō: nǐ hǎo. Сказанное идёт до конца предложения, поэтому его ma или le остаётся внутри."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:shuo1}}: {{word:ni3}} {{word:hao3}} {{word:ma}}? (He says: how are you?)"],ru:["{{Word:ta1}} {{word:shuo1}}: {{word:ni3}} {{word:hao3}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:xiao3}} {{word:nv3}}-{{word:ren2}} {{word:lai2}} {{word:le}}, {{word:shuo1}}: {{word:wo3}} {{word:ai4}} {{word:ni3}}. (The girl came and said: I love you.)"],ru:["{{Word:xiao3}} {{word:nv3}}-{{word:ren2}} {{word:lai2}} {{word:le}}, {{word:shuo1}}: {{word:wo3}} {{word:ai4}} {{word:ni3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 7 · Pre-Verbs"],zh:[],ru:["Урок 7 · Слова перед глаголом"]},items:[{text:{en:["**Who + {{word:yao4}} + verb** — Who wants to do the verb. Says what someone wants to do: yào (want) or xiǎng (would like) goes before the verb."],ru:["**Who + {{word:yao4}} + verb** — Говорит, что кто-то хочет сделать: yào («хотеть») или xiǎng («хотелось бы») стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:yao4}} {{word:he1}} {{word:shui3}}. (I want to drink water.)"],ru:["{{Word:wo3}} {{word:yao4}} {{word:he1}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:xiang3}} {{word:chi1}} {{word:fan4}}. (I'd like to eat.)"],ru:["{{Word:wo3}} {{word:xiang3}} {{word:chi1}} {{word:fan4}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:yao4}} {{word:deng3}} {{word:ma}}? (Do you want to wait?)"],ru:["{{Word:ni3}} {{word:yao4}} {{word:deng3}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**{{word:neng2}} / {{word:bu4}} {{word:neng2}}** — Can / cannot. Néng on its own, or with bù, answers whether something can be done: bù néng, no, you can't."],ru:["**{{word:neng2}} / {{word:bu4}} {{word:neng2}}** — Néng само по себе, или с bù, отвечает, можно ли это сделать: bù néng — нет, нельзя."],zh:[]},items:[{text:{en:["{{Word:bu4}} {{word:neng2}}, {{word:ni3}} {{word:bu4}} {{word:neng2}} {{word:qu4}}. (No, you can't go.)"],ru:["{{Word:bu4}} {{word:neng2}}, {{word:ni3}} {{word:bu4}} {{word:neng2}} {{word:qu4}}."],zh:[]}}]},{text:{en:[`**Who + {{word:neng2}} + verb** — Who can do the verb. Says what someone can do: néng goes before the verb, and bù goes before néng for "can't". Néng also means may.`],ru:["**Who + {{word:neng2}} + verb** — Говорит, что кто-то может сделать: néng стоит перед глаголом, а bù перед néng значит «не может». Néng значит и «можно»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:neng2}} {{word:ting1}}. (I can hear.)"],ru:["{{Word:wo3}} {{word:neng2}} {{word:ting1}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:bu4}} {{word:neng2}} {{word:chi1}}. (He can't eat.)"],ru:["{{Word:ta1}} {{word:bu4}} {{word:neng2}} {{word:chi1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:neng2}} {{word:kan4}} {{word:ma}}? (May I look?)"],ru:["{{Word:wo3}} {{word:neng2}} {{word:kan4}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Who + {{word:xue2}} + verb** — Who learns to do the verb. Says someone is learning to do something: xué goes before the verb."],ru:["**Who + {{word:xue2}} + verb** — Говорит, что кто-то учится что-то делать: xué стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:xue2}} {{word:xie3}}. (I'm learning to write.)"],ru:["{{Word:wo3}} {{word:xue2}} {{word:xie3}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:yao4}} {{word:xue2}} {{word:xie3}} {{word:ma}}? (Do you want to learn to write?)"],ru:["{{Word:ni3}} {{word:yao4}} {{word:xue2}} {{word:xie3}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Who + {{word:ai4}} + verb** — Who loves doing the verb. Says someone loves doing something: ài goes before the verb."],ru:["**Who + {{word:ai4}} + verb** — Говорит, что кто-то любит что-то делать: ài стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:ai4}} {{word:kan4}}. (She loves to read.)"],ru:["{{Word:ta1}} {{word:ai4}} {{word:kan4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}. (I love listening to you talk.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:ting1}} {{word:ni3}} {{word:shuo1}}."],zh:[]}}]},{text:{en:["**Who + {{word:zhi1dao4}} {{word:zen3me}} + verb** — Who knows how to do the verb. Says you know how to do something: zhīdào zěnme goes before the verb."],ru:["**Who + {{word:zhi1dao4}} {{word:zen3me}} + verb** — Говорит, что вы знаете, как что-то делать: zhīdào zěnme стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:zhi1dao4}} {{word:zen3me}} {{word:xie3}}. (I know how to write.)"],ru:["{{Word:wo3}} {{word:zhi1dao4}} {{word:zen3me}} {{word:xie3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:bu4}} {{word:zhi1dao4}} {{word:zen3me}} {{word:xie3}}. (He doesn't know how to write it.)"],ru:["{{Word:ta1}} {{word:bu4}} {{word:zhi1dao4}} {{word:zen3me}} {{word:xie3}}."],zh:[]}}]},{text:{en:["**Who + {{word:zhi1dao4}} + sentence** — Who knows what the sentence says. Zhīdào can be followed by a whole sentence: what you know is what happened, or who did it."],ru:["**Who + {{word:zhi1dao4}} + sentence** — После zhīdào может идти целое предложение: то, что вы знаете, — это то, что случилось, или кто это сделал."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:zhi1dao4}} {{word:ta1}} {{word:qu4}}. (I know he went.)"],ru:["{{Word:wo3}} {{word:zhi1dao4}} {{word:ta1}} {{word:qu4}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:zhi1dao4}} {{word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}} {{word:ma}}? (Do you know what happened?)"],ru:["{{Word:ni3}} {{word:zhi1dao4}} {{word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Who + {{word:ke3neng2}} + verb** — Who might do the verb. Says it might be so: kěnéng goes before the verb."],ru:["**Who + {{word:ke3neng2}} + verb** — Говорит, что, возможно, это так: kěnéng стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:ke3neng2}} {{word:zhi1dao4}}. (He might know.)"],ru:["{{Word:ta1}} {{word:ke3neng2}} {{word:zhi1dao4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:ke3neng2}} {{word:bu4}} {{word:neng2}} {{word:deng3}}. (I might not be able to wait.)"],ru:["{{Word:wo3}} {{word:ke3neng2}} {{word:bu4}} {{word:neng2}} {{word:deng3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 8 · Time 1 — When it happens"],zh:[],ru:["Урок 8 · Время 1 — Когда это происходит"]},items:[{text:{en:["**Who + verb + {{word:le}}** — Who did the verb. Says something is done: le goes right after the verb. The verb itself never changes."],ru:["**Who + verb + {{word:le}}** — Говорит, что что-то сделано: le стоит сразу после глагола. Сам глагол не меняется."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:chi1}} {{word:le}}. (I ate.)"],ru:["{{Word:wo3}} {{word:chi1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:kan4}} {{word:le}} {{word:ma}}? (Did you see it?)"],ru:["{{Word:ni3}} {{word:kan4}} {{word:le}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}}? (What happened?)"],ru:["{{Word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}}?"],zh:[]}}]},{text:{en:["**Thing {{word:mei2}} {{word:le}}** — The thing is gone. Méi le says it is gone: wèn-tí jiù méi le, the problem is gone. Wán le says it is used up: shuǐ wán le."],ru:["**Thing {{word:mei2}} {{word:le}}** — Méi le говорит «нет больше»: wèn-tí jiù méi le — проблемы больше нет. Wán le говорит «кончилось»: shuǐ wán le — вода кончилась."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:de}} {{word:shui3}} {{word:wan2}} {{word:le}}. (My water is used up.)"],ru:["{{Word:wo3}} {{word:de}} {{word:shui3}} {{word:wan2}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wen4}}-{{word:ti2}} {{word:jiu4}} {{word:mei2}} {{word:le}}. (The problem is gone.)"],ru:["{{Word:wen4}}-{{word:ti2}} {{word:jiu4}} {{word:mei2}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:xue2}}-{{word:wan2}} {{word:le}} {{word:zhong1}}-{{word:xue2}}. (He has finished middle school.)"],ru:["{{Word:ta1}} {{word:xue2}}-{{word:wan2}} {{word:le}} {{word:zhong1}}-{{word:xue2}}."],zh:[]}}]},{text:{en:["**Who + {{word:zai4}} + verb** — Who is doing the verb. Says something is happening right now: zài goes before the verb, like -ing in English."],ru:["**Who + {{word:zai4}} + verb** — Говорит, что это происходит прямо сейчас: zài стоит перед глаголом, как -ing в английском."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:zai4}} {{word:shui4jiao4}}. (She's sleeping.)"],ru:["{{Word:ta1}} {{word:zai4}} {{word:shui4jiao4}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:zai4}} {{word:kan4}} {{word:shen2me}}? (What are you looking at?)"],ru:["{{Word:ni3}} {{word:zai4}} {{word:kan4}} {{word:shen2me}}?"],zh:[]}}]},{text:{en:["**Who + {{word:hui4}} + verb** — Who will do the verb. Says something will happen: huì goes before the verb."],ru:["**Who + {{word:hui4}} + verb** — Говорит, что это произойдёт: huì стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:hui4}} {{word:chi1}}. (I will eat.)"],ru:["{{Word:wo3}} {{word:hui4}} {{word:chi1}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:hui4}} {{word:shui4jiao4}} {{word:ma}}? (Will you sleep?)"],ru:["{{Word:ni3}} {{word:hui4}} {{word:shui4jiao4}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**{{word:kuai4}} + verb / {{word:kuai4}} {{word:yao4}} + verb {{word:le}}** — Do it quickly / is about to do it. Kuài before a verb says hurry or quickly: kuài lái, come quickly. Kuài yào before a verb and le says about to: tā kuài yào lái le, he is about to come."],ru:["**{{word:kuai4}} + verb / {{word:kuai4}} {{word:yao4}} + verb {{word:le}}** — Kuài перед глаголом значит «быстро»: kuài lái — иди скорее. Kuài yào перед глаголом и le значит «вот-вот»: tā kuài yào lái le — он вот-вот придёт."],zh:[]},items:[{text:{en:["{{Word:kuai4}} {{word:lai2}}! (Come quickly!)"],ru:["{{Word:kuai4}} {{word:lai2}}!"],zh:[]}},{text:{en:["{{Word:ta1}} {{word:kuai4}} {{word:yao4}} {{word:lai2}} {{word:le}}. (He is about to come.)"],ru:["{{Word:ta1}} {{word:kuai4}} {{word:yao4}} {{word:lai2}} {{word:le}}."],zh:[]}}]},{text:{en:["**Who + verb-{{word:guo4}}** — Who has done the verb before. Says you have done something before: guò goes right after the verb."],ru:["**Who + verb-{{word:guo4}}** — Говорит, что вы уже делали это раньше: guò стоит сразу после глагола."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:kan4}} {{word:guo4}} {{word:zhe4}}-{{light:ge4}} {{word:dong4}}-{{word:wu4}}. (I've seen this animal before.)"],ru:["{{Word:wo3}} {{word:kan4}} {{word:guo4}} {{word:zhe4}}-{{light:ge4}} {{word:dong4}}-{{word:wu4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:shuo1}} {{word:guo4}}. (He has said it before.)"],ru:["{{Word:ta1}} {{word:shuo1}} {{word:guo4}}."],zh:[]}}]},{text:{en:["**Time, who + verb** — When, who does the verb. Says when: the time comes first, then a comma, then the rest. A time can also stand right after the doer."],ru:["**Time, who + verb** — Говорит, когда: сначала время, потом запятая, потом остальное. Время может стоять и сразу после того, кто делает."],zh:[]},items:[{text:{en:["{{Word:yue4}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:shui4jiao4}}. (At night, I sleep.)"],ru:["{{Word:yue4}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:shui4jiao4}}."],zh:[]}},{text:{en:["{{Word:xian4}}-{{word:zai4}}, {{word:wo3}} {{word:yao4}} {{word:shui4jiao4}}. (Now I want to sleep.)"],ru:["{{Word:xian4}}-{{word:zai4}}, {{word:wo3}} {{word:yao4}} {{word:shui4jiao4}}."],zh:[]}},{text:{en:["{{Word:shen2me}} {{word:shi2}}-{{word:jian1}} {{word:ni3}} {{word:chi1}}? (When do you eat?)"],ru:["{{Word:shen2me}} {{word:shi2}}-{{word:jian1}} {{word:ni3}} {{word:chi1}}?"],zh:[]}},{text:{en:["{{Word:ta1}} {{word:xian4}}-{{word:zai4}} {{word:zai4}} {{word:shui4jiao4}}. (He's sleeping now.)"],ru:["{{Word:ta1}} {{word:xian4}}-{{word:zai4}} {{word:zai4}} {{word:shui4jiao4}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 9 · Time 2 — Around an action"],zh:[],ru:["Урок 9 · Время 2 — Вокруг действия"]},items:[{text:{en:["**number {{word:dian3}} number {{word:fen1}}** — Hours and minutes. After the hour, a number and fēn says the minutes: sān diǎn wǔ fēn, five past three."],ru:["**number {{word:dian3}} number {{word:fen1}}** — После часа число и fēn называют минуты: sān diǎn wǔ fēn — пять минут четвёртого."],zh:[]},items:[{text:{en:["{{Word:xian4}}-{{word:zai4}} {{word:shi4}} {{word:san1}} {{word:dian3}} {{word:wu3}} {{word:fen1}}. (It's five past three.)"],ru:["{{Word:xian4}}-{{word:zai4}} {{word:shi4}} {{word:san1}} {{word:dian3}} {{word:wu3}} {{word:fen1}}."],zh:[]}}]},{text:{en:["**time word + number {{word:hao4}}** — The date is that. A time word and a number with hào names the date: jīn-tiān shí hào, today is the tenth."],ru:["**time word + number {{word:hao4}}** — Слово времени и число с hào называют дату: jīn-tiān shí hào — сегодня десятое."],zh:[]},items:[{text:{en:["{{Word:jin1}}-{{word:tian1}} {{word:shi2}} {{word:hao4}}. (Today is the tenth.)"],ru:["{{Word:jin1}}-{{word:tian1}} {{word:shi2}} {{word:hao4}}."],zh:[]}}]},{text:{en:["**span {{word:de}} {{word:zui4}}-{{word:hou4}} + span** — The last days of that span. A span of days, de, and zuì-hòu name its last days: qī tiān de zuì-hòu liǎng tiān, the last two of the seven days."],ru:["**span {{word:de}} {{word:zui4}}-{{word:hou4}} + span** — Промежуток дней, de и zuì-hòu называют его последние дни: qī tiān de zuì-hòu liǎng tiān — последние два из семи дней."],zh:[]},items:[{text:{en:["{{Word:qi1}} {{word:tian1}} {{word:de}} {{word:zui4}}-{{word:hou4}} {{word:liang3}} {{word:tian1}}, {{word:wo3}} {{word:zai4}} {{word:jia1}}. (At the weekend I am at home.)"],ru:["{{Word:qi1}} {{word:tian1}} {{word:de}} {{word:zui4}}-{{word:hou4}} {{word:liang3}} {{word:tian1}}, {{word:wo3}} {{word:zai4}} {{word:jia1}}."],zh:[]}}]},{text:{en:["**{{word:xia4}}-{{word:ge4}} / {{word:shang4}}-{{word:ge4}} + time word** — Next / last time. Xià-gè and shàng-gè before a time word say next and last: xià-gè yuè, next month. Xià yī gè rè-de shí-jiān is next summer."],ru:["**{{word:xia4}}-{{word:ge4}} / {{word:shang4}}-{{word:ge4}} + time word** — Xià-gè и shàng-gè перед словом времени значат «следующий» и «прошлый»: xià-gè yuè — в следующем месяце. Xià yī gè rè-de shí-jiān — следующим летом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:xia4}}-{{word:ge4}} {{word:yue4}} {{word:lai2}}. (I'm coming next month.)"],ru:["{{Word:wo3}} {{word:xia4}}-{{word:ge4}} {{word:yue4}} {{word:lai2}}."],zh:[]}},{text:{en:["{{Word:xia4}} {{word:yi1}} {{word:ge4}} {{word:re4}} {{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:ni3}} {{word:ye3}} {{word:yao4}} {{word:zuo4}}. (Next summer, you have to work too.)"],ru:["{{Word:xia4}} {{word:yi1}} {{word:ge4}} {{word:re4}} {{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:ni3}} {{word:ye3}} {{word:yao4}} {{word:zuo4}}."],zh:[]}}]},{text:{en:["**{{word:shen2me}} {{word:shi2}}-{{word:jian1}}** — When? Shénme shí-jiān asks when: nǐ shénme shí-jiān lái, when are you coming?"],ru:["**{{word:shen2me}} {{word:shi2}}-{{word:jian1}}** — Shénme shí-jiān спрашивает «когда»: nǐ shénme shí-jiān lái — когда ты придёшь?"],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:shen2me}} {{word:shi2}}-{{word:jian1}} {{word:lai2}}? (When are you coming?)"],ru:["{{Word:ni3}} {{word:shen2me}} {{word:shi2}}-{{word:jian1}} {{word:lai2}}?"],zh:[]}}]},{text:{en:["**span + {{word:hou4}} / {{word:qian2}}** — After / before that long. A length of time and hòu or qián says how long after or before: sān tiān hòu, in three days."],ru:["**span + {{word:hou4}} / {{word:qian2}}** — Промежуток времени и hòu или qián говорят, через сколько или сколько назад: sān tiān hòu — через три дня."],zh:[]},items:[{text:{en:["{{Word:san1}} {{word:tian1}} {{word:hou4}} {{word:wo3}} {{word:lai2}}. (I'll come in three days.)"],ru:["{{Word:san1}} {{word:tian1}} {{word:hou4}} {{word:wo3}} {{word:lai2}}."],zh:[]}},{text:{en:["{{Word:liang3}} {{word:tian1}} {{word:qian2}} {{word:ta1}} {{word:hui2}} {{word:jia1}} {{word:le}}. (He went home two days ago.)"],ru:["{{Word:liang3}} {{word:tian1}} {{word:qian2}} {{word:ta1}} {{word:hui2}} {{word:jia1}} {{word:le}}."],zh:[]}}]},{text:{en:["**{{word:na4}}-{{word:ge4}} {{word:shi2}}-{{word:jian1}}** — At that time. Nà-gè shí-jiān is at that time: nà-gè shí-jiān wǒ zài jiā, at that time I was at home."],ru:["**{{word:na4}}-{{word:ge4}} {{word:shi2}}-{{word:jian1}}** — Nà-gè shí-jiān — в то время: nà-gè shí-jiān wǒ zài jiā — в то время я был дома."],zh:[]},items:[{text:{en:["{{Word:na4}}-{{word:ge4}} {{word:shi2}}-{{word:jian1}} {{word:wo3}} {{word:zai4}} {{word:jia1}}. (At that time I was at home.)"],ru:["{{Word:na4}}-{{word:ge4}} {{word:shi2}}-{{word:jian1}} {{word:wo3}} {{word:zai4}} {{word:jia1}}."],zh:[]}}]},{text:{en:['**Who + verb-{{word:de}} {{word:shi2}}-{{word:jian1}}, the rest** — When who does the verb, the rest. Says "when" something happens: say "the time of" it, with -de shíjiān after the action, then a comma.'],ru:["**Who + verb-{{word:de}} {{word:shi2}}-{{word:jian1}}, the rest** — Говорит, «когда» что-то происходит: «время» действия, то есть -de shíjiān после действия, потом запятая."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:chi1}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:bu4}} {{word:shuo1}}. (When I eat, I don't talk.)"],ru:["{{Word:wo3}} {{word:chi1}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:bu4}} {{word:shuo1}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:shui4jiao4}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:wan2r}}. (When he sleeps, I play.)"],ru:["{{Word:ta1}} {{word:shui4jiao4}}-{{word:de}} {{word:shi2}}-{{word:jian1}}, {{word:wo3}} {{word:wan2r}}."],zh:[]}}]},{text:{en:['**{{word:cong2}}-{{word:qian2}} / {{word:hou4}}-{{word:lai2}}** — Before / later. Cóng-qián means before, in the past, and hòu-lái means later, after that: cóng-qián wǒ zài "Zhōngguó", I used to be in China. Wèi-lái is the time still to come. Xiǎo-de shí-jiān is as a child; xīn-nián is the New Year.'],ru:['**{{word:cong2}}-{{word:qian2}} / {{word:hou4}}-{{word:lai2}}** — Cóng-qián значит «раньше», hòu-lái — «потом, после этого»: cóng-qián wǒ zài "Zhōngguó" — раньше я был в Китае. Wèi-lái — время, которое ещё придёт. Xiǎo-de shí-jiān — в детстве; xīn-nián — Новый год.'],zh:[]},items:[{text:{en:["{{Word:cong2}}-{{word:qian2}} {{word:wo3}} {{word:zai4}} {{word:jia1}}. (I used to be at home.)"],ru:["{{Word:cong2}}-{{word:qian2}} {{word:wo3}} {{word:zai4}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:hou4}}-{{word:lai2}} {{word:wo3}} {{word:zai4}} {{word:jia1}}. (Later I was at home.)"],ru:["{{Word:hou4}}-{{word:lai2}} {{word:wo3}} {{word:zai4}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:wei4}}-{{word:lai2}} {{word:wo3}} {{word:xiang3}} {{word:hui2}} {{word:jia1}}. (In the future I want to go home.)"],ru:["{{Word:wei4}}-{{word:lai2}} {{word:wo3}} {{word:xiang3}} {{word:hui2}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:xiao3}}-{{word:de}} {{word:shi2}}-{{word:jian1}} {{word:wo3}} {{word:ai4}} {{word:shui3}}. (As a child I loved water.)"],ru:["{{Word:xiao3}}-{{word:de}} {{word:shi2}}-{{word:jian1}} {{word:wo3}} {{word:ai4}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:xin1}}-{{word:nian2}} {{word:wo3}}-{{word:men}} {{word:hui2}} {{word:jia1}}. (We go home for the New Year.)"],ru:["{{Word:xin1}}-{{word:nian2}} {{word:wo3}}-{{word:men}} {{word:hui2}} {{word:jia1}}."],zh:[]}}]},{text:{en:["**Who + verb-{{word:wan2}} {{word:le}}** — Who finished the verb. Says you finished doing something: wán joins the verb, and le follows."],ru:["**Who + verb-{{word:wan2}} {{word:le}}** — Говорит, что вы закончили что-то делать: wán присоединяется к глаголу, а затем идёт le."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}}. (I finished eating.)"],ru:["{{Word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:xie3}}-{{word:wan2}} {{word:le}} {{word:ma}}? (Did you finish writing?)"],ru:["{{Word:ni3}} {{word:xie3}}-{{word:wan2}} {{word:le}} {{word:ma}}?"],zh:[]}}]},{text:{en:['**verb-{{word:wan2}} {{word:hou4}}, the rest** — After the verb, the rest. Says "after doing something": hòu goes after the finished action, then a comma and the rest.'],ru:["**verb-{{word:wan2}} {{word:hou4}}, the rest** — Говорит «после того, как что-то сделано»: hòu стоит после законченного действия, потом запятая и остальное."],zh:[]},items:[{text:{en:["{{Word:chi1}}-{{word:wan2}} {{word:hou4}}, {{word:wo3}} {{word:shui4jiao4}}. (After eating, I sleep.)"],ru:["{{Word:chi1}}-{{word:wan2}} {{word:hou4}}, {{word:wo3}} {{word:shui4jiao4}}."],zh:[]}},{text:{en:["{{Word:chi1}}-{{word:wan2}} {{word:hou4}}, {{word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}}? (After eating, what happened?)"],ru:["{{Word:chi1}}-{{word:wan2}} {{word:hou4}}, {{word:fa1}}-{{word:sheng1}} {{word:le}} {{word:shen2me}}?"],zh:[]}}]},{text:{en:["**Who + {{word:kai1shi3}} + verb** — Who starts to do the verb. Says something starts: kāishǐ goes before the verb."],ru:["**Who + {{word:kai1shi3}} + verb** — Говорит, что что-то начинается: kāishǐ стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:kai1shi3}} {{word:wan2r}} {{word:le}}. (I started to play.)"],ru:["{{Word:wo3}} {{word:kai1shi3}} {{word:wan2r}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:kai1shi3}} {{word:xie3}} {{word:le}} {{word:ma}}? (Have you started writing?)"],ru:["{{Word:ni3}} {{word:kai1shi3}} {{word:xie3}} {{word:le}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Who + verb + {{word:yi1}}-{{word:xia4}}** — Who does the verb for a moment. Says to do something for a moment: yī-xià goes after the verb. It also softens a request."],ru:["**Who + verb + {{word:yi1}}-{{word:xia4}}** — Говорит, что что-то делается ненадолго: yī-xià стоит после глагола. Оно же смягчает просьбу."],zh:[]},items:[{text:{en:["{{Word:deng3}} {{word:yi1}}-{{word:xia4}}. (Wait a moment.)"],ru:["{{Word:deng3}} {{word:yi1}}-{{word:xia4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:you4}} {{word:kan4}} {{word:le}} {{word:yi1}}-{{word:xia4}}. (I had another look.)"],ru:["{{Word:wo3}} {{word:you4}} {{word:kan4}} {{word:le}} {{word:yi1}}-{{word:xia4}}."],zh:[]}}]},{text:{en:["**Who + {{word:you4}} + verb + {{word:le}}** — Who did the verb again. Says something happens again: yòu goes before the verb, and le after it."],ru:["**Who + {{word:you4}} + verb + {{word:le}}** — Говорит, что это происходит снова: yòu стоит перед глаголом, а le после него."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:you4}} {{word:chi1}} {{word:le}}. (He ate again.)"],ru:["{{Word:ta1}} {{word:you4}} {{word:chi1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:you4}} {{word:yao4}} {{word:chi1}} {{word:le}}. (I'm going to eat again.)"],ru:["{{Word:wo3}} {{word:you4}} {{word:yao4}} {{word:chi1}} {{word:le}}."],zh:[]}}]},{text:{en:["**Who + verb + {{word:hen3}} {{word:duo1}} {{word:ci4}}** — Who does the verb many times. Says how many times: cì goes after hěn duō or duōshǎo, after a number, or after zhè (this time)."],ru:["**Who + verb + {{word:hen3}} {{word:duo1}} {{word:ci4}}** — Говорит, сколько раз: cì стоит после hěn duō или duōshǎo, после числа или после zhè («этот раз»)."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:kan4}}-{{word:guo4}} {{word:hen3}}-{{word:duo1}} {{word:ci4}}. (I've seen it many times.)"],ru:["{{Word:wo3}} {{word:kan4}}-{{word:guo4}} {{word:hen3}}-{{word:duo1}} {{word:ci4}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:chi1}}-{{word:guo4}} {{word:duo1}}-{{word:shao3}} {{word:ci4}}? (How many times have you eaten it?)"],ru:["{{Word:ni3}} {{word:chi1}}-{{word:guo4}} {{word:duo1}}-{{word:shao3}} {{word:ci4}}?"],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:ci4}} {{word:wo3}} {{word:deng3}} {{word:ni3}}. (This time I'll wait for you.)"],ru:["{{Word:zhe4}} {{word:ci4}} {{word:wo3}} {{word:deng3}} {{word:ni3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 10 · Space 1 — Where it is"],zh:[],ru:["Урок 10 · Пространство 1 — Где это"]},items:[{text:{en:["**Who + {{word:zai4}} + place** — Who is at the place. Says where someone or something is: zài goes before the place. A place can also come before the verb: where it is done."],ru:["**Who + {{word:zai4}} + place** — Говорит, где кто-то или что-то находится: zài стоит перед местом. Место может стоять и перед глаголом: где это делается."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:liu2}} {{word:zai4}} {{word:jia1}}. (He stays at home.)"],ru:["{{Word:ta1}} {{word:liu2}} {{word:zai4}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:zai4}} {{word:jia1}} {{word:zhao3}}. (I'm looking for it at home.)"],ru:["{{Word:wo3}} {{word:zai4}} {{word:jia1}} {{word:zhao3}}."],zh:[]}}]},{text:{en:["**{{word:zai4}} + place, sentence** — At the place: the sentence. A place with zài can come first, then the sentence: zài jiā wǒ jué-dé hǎo, at home I feel good."],ru:["**{{word:zai4}} + place, sentence** — Место с zài может стоять первым, затем предложение: zài jiā wǒ jué-dé hǎo — дома мне хорошо."],zh:[]},items:[{text:{en:["{{Word:zai4}} {{word:jia1}} {{word:wo3}} {{word:jue2}}-{{word:de2}} {{word:hao3}}. (At home I feel good.)"],ru:["{{Word:zai4}} {{word:jia1}} {{word:wo3}} {{word:jue2}}-{{word:de2}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zai4}} + place-{{word:li3}} / place-{{word:shang4}}** — The thing is in / on the place. Says in or on something: lǐ (in) or shàng (on) joins the place."],ru:["**Thing + {{word:zai4}} + place-{{word:li3}} / place-{{word:shang4}}** — Говорит «внутри» или «на»: lǐ («в») или shàng («на») присоединяется к месту."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:zai4}} {{word:bao1}}-{{word:li3}}. (The water is in the bag.)"],ru:["{{Word:shui3}} {{word:zai4}} {{word:bao1}}-{{word:li3}}."],zh:[]}},{text:{en:["{{Word:gong1}}-{{word:ju4}} {{word:zai4}} {{word:di4}}-{{word:shang4}}. (The tool is on the floor.)"],ru:["{{Word:gong1}}-{{word:ju4}} {{word:zai4}} {{word:di4}}-{{word:shang4}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zai4}} + place {{word:xia4}}-{{word:mian4}} / {{word:qian2}}-{{word:mian4}} / {{word:hou4}}-{{word:mian4}} / {{word:pang2}}-{{word:bian1}}** — The thing is under / in front of / behind / beside the place. Says under, in front of, behind or beside something: xià-miàn, qián-miàn, hòu-miàn or páng-biān goes right after the place."],ru:["**Thing + {{word:zai4}} + place {{word:xia4}}-{{word:mian4}} / {{word:qian2}}-{{word:mian4}} / {{word:hou4}}-{{word:mian4}} / {{word:pang2}}-{{word:bian1}}** — Говорит «под», «перед», «за» или «рядом»: xià-miàn, qián-miàn, hòu-miàn или páng-biān стоит сразу после места."],zh:[]},items:[{text:{en:["{{Word:dong4}}-{{word:wu4}} {{word:zai4}} {{word:bao1}} {{word:xia4}}-{{word:mian4}}. (The animal is under the bag.)"],ru:["{{Word:dong4}}-{{word:wu4}} {{word:zai4}} {{word:bao1}} {{word:xia4}}-{{word:mian4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:zai4}} {{word:wo3}} {{word:qian2}}-{{word:mian4}}. (He is in front of me.)"],ru:["{{Word:ta1}} {{word:zai4}} {{word:wo3}} {{word:qian2}}-{{word:mian4}}."],zh:[]}},{text:{en:["{{Word:bao1}} {{word:zai4}} {{word:jia1}} {{word:hou4}}-{{word:mian4}}. (The bag is behind the house.)"],ru:["{{Word:bao1}} {{word:zai4}} {{word:jia1}} {{word:hou4}}-{{word:mian4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:zai4}} {{word:ta1}} {{word:pang2}}-{{word:bian1}}. (I am beside him.)"],ru:["{{Word:wo3}} {{word:zai4}} {{word:ta1}} {{word:pang2}}-{{word:bian1}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zai4}} + X {{word:zhong1}}-{{word:jian1}}** — The thing is between X. Says between or in the middle: zhōng-jiān goes after the places or people."],ru:["**Thing + {{word:zai4}} + X {{word:zhong1}}-{{word:jian1}}** — Говорит «между» или «посередине»: zhōng-jiān стоит после мест или людей."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:zai4}} {{word:wo3}}-{{word:men}} {{word:zhong1}}-{{word:jian1}}. (He's between us.)"],ru:["{{Word:ta1}} {{word:zai4}} {{word:wo3}}-{{word:men}} {{word:zhong1}}-{{word:jian1}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 11 · Space 2 — Moving"],zh:[],ru:["Урок 11 · Пространство 2 — Движение"]},items:[{text:{en:["**Who + {{word:cong2}} + place + {{word:lai2}}** — Who comes from the place. Says where you come from: cóng goes before the place, then the verb, lái."],ru:["**Who + {{word:cong2}} + place + {{word:lai2}}** — Говорит, откуда вы идёте: cóng стоит перед местом, потом глагол, lái."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:cong2}} {{word:jia1}} {{word:lai2}}. (He comes from home.)"],ru:["{{Word:ta1}} {{word:cong2}} {{word:jia1}} {{word:lai2}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:cong2}} {{word:na3}}-{{word:li3}} {{word:lai2}}? (Where do you come from?)"],ru:["{{Word:ni3}} {{word:cong2}} {{word:na3}}-{{word:li3}} {{word:lai2}}?"],zh:[]}}]},{text:{en:["**Who + verb + place + {{word:le}}** — Who has now done the verb at the place. Says something has now happened: le goes at the end of what is said."],ru:["**Who + verb + place + {{word:le}}** — Говорит, что это уже случилось: le стоит в конце сказанного."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:dao4}} {{word:jia1}} {{word:le}}. (I've arrived home.)"],ru:["{{Word:wo3}} {{word:dao4}} {{word:jia1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wo3}}-{{word:men}} {{word:dao4}} {{word:jia1}} {{word:le}}. (We've arrived home.)"],ru:["{{Word:wo3}}-{{word:men}} {{word:dao4}} {{word:jia1}} {{word:le}}."],zh:[]}}]},{text:{en:["**Who + {{word:dao4}} / {{word:qu4}} + place** — Who gets to / goes to the place. Says where someone gets to or is heading: dào (arrive) and the place, or qù (go) and the place. Qù is on the way, dào is there: wǒ qù bàba-māma-de jiā, I'm going to my parents' home; wǒ dào bàba-māma-de jiā le, I'm there now."],ru:["**Who + {{word:dao4}} / {{word:qu4}} + place** — Говорит, куда кто-то добрался или идёт: dào («добраться») и место, или qù («идти») и место. Qù — в пути, dào — уже на месте: wǒ qù bàba-māma-de jiā — я иду к родителям; wǒ dào bàba-māma-de jiā le — я уже у них."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:dao4}} {{word:jia1}} {{word:le}}. (I've arrived home.)"],ru:["{{Word:wo3}} {{word:dao4}} {{word:jia1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:dao4}} {{word:na4}}-{{light:ge4}} {{word:di4}}-{{light:fang1}} {{word:le}}. (She got to that place.)"],ru:["{{Word:ta1}} {{word:dao4}} {{word:na4}}-{{light:ge4}} {{word:di4}}-{{light:fang1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:qu4}} {{word:ba4ba}}-{{word:ma1ma}}-{{word:de}} {{word:jia1}}. (I'm going to my parents' home.)"],ru:["{{Word:wo3}} {{word:qu4}} {{word:ba4ba}}-{{word:ma1ma}}-{{word:de}} {{word:jia1}}."],zh:[]}}]},{text:{en:["**Who + verb-{{word:shang4}}-{{word:qu4}}** — Who does the verb, going up and away. A direction word and lái or qù go together right after a verb and say which way it goes: fēi-shàng-qù, fly up and away; ná-xià-lái, take it down toward you."],ru:["**Who + verb-{{word:shang4}}-{{word:qu4}}** — Слово направления и lái или qù стоят вместе сразу после глагола и говорят, куда он идёт: fēi-shàng-qù — взлететь; ná-xià-lái — снять и принести вниз."],zh:[]},items:[{text:{en:["{{Word:dong4}}-{{word:wu4}} {{word:fei1}}-{{word:shang4}}-{{word:qu4}}. (The animal flies up and away.)"],ru:["{{Word:dong4}}-{{word:wu4}} {{word:fei1}}-{{word:shang4}}-{{word:qu4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:na2}}-{{word:xia4}}-{{word:lai2}} {{word:shui3}}. (He takes the water down toward you.)"],ru:["{{Word:ta1}} {{word:na2}}-{{word:xia4}}-{{word:lai2}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:shang4}}-{{word:qu4}}. (You go up.)"],ru:["{{Word:ni3}} {{word:shang4}}-{{word:qu4}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zai4}} (+ place) + {{word:fu4jin4}}** — The thing is near (the place). Says something is near: fùjìn goes after zài, or after zài and a place."],ru:["**Thing + {{word:zai4}} (+ place) + {{word:fu4jin4}}** — Говорит, что это рядом: fùjìn стоит после zài или после zài и места."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:zai4}} {{word:jia1}} {{word:fu4jin4}}. (The water is near home.)"],ru:["{{Word:shui3}} {{word:zai4}} {{word:jia1}} {{word:fu4jin4}}."],zh:[]}}]},{text:{en:["**{{word:hen3}} {{word:duo1}} + noun** — Many of the noun. Says there are many of something: hěn duō goes right before the noun."],ru:["**{{word:hen3}} {{word:duo1}} + noun** — Говорит, что чего-то много: hěn duō стоит прямо перед существительным."],zh:[]},items:[{text:{en:["{{Word:lu4}}-{{word:shang4}} {{word:you3}} {{word:hen3}} {{word:duo1}} {{word:ren2}}. (There are lots of people on the road.)"],ru:["{{Word:lu4}}-{{word:shang4}} {{word:you3}} {{word:hen3}} {{word:duo1}} {{word:ren2}}."],zh:[]}}]},{text:{en:["**Who + verb + verb** — Who does one thing, then another. Two actions can follow each other, in the order they happen: zǒu lù qù, walk and go there."],ru:["**Who + verb + verb** — Два действия могут идти одно за другим, в том порядке, в каком происходят: zǒu lù qù — идти пешком туда."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:zou3}} {{word:lu4}} {{word:qu4}}. (He walks there.)"],ru:["{{Word:ta1}} {{word:zou3}} {{word:lu4}} {{word:qu4}}."],zh:[]}},{text:{en:["{{Word:dong4}}-{{word:wu4}} {{word:tong1}}-{{word:guo4}} {{word:zhe4}}-{{light:ge4}} {{word:kou3}} {{word:chu1}}-{{word:qu4}} {{word:le}}. (The animal went out through this opening.)"],ru:["{{Word:dong4}}-{{word:wu4}} {{word:tong1}}-{{word:guo4}} {{word:zhe4}}-{{light:ge4}} {{word:kou3}} {{word:chu1}}-{{word:qu4}} {{word:le}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 12 · Modifiers 1 — How much"],zh:[],ru:["Урок 12 · Уточнения 1 — Насколько"]},items:[{text:{en:["**Subject {{word:hen3}} adjective verb** — Subject does the verb very adjectively. How or how much someone does it: hěn and a describing word go before the verb."],ru:["**Subject {{word:hen3}} adjective verb** — Как или насколько кто-то это делает: hěn и описывающее слово стоят перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:hen3}} {{word:zao3}} {{word:lai2}}. (I come very early.)"],ru:["{{Word:wo3}} {{word:hen3}} {{word:zao3}} {{word:lai2}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:hen3}} {{word:kuai4}} {{word:zou3}}. (He walks very fast.)"],ru:["{{Word:ta1}} {{word:hen3}} {{word:kuai4}} {{word:zou3}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:gong1}}-{{word:ju4}} {{word:hen3}} {{word:you3}} {{word:jia4zhi2}}. (This tool is very valuable.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:gong1}}-{{word:ju4}} {{word:hen3}} {{word:you3}} {{word:jia4zhi2}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zhen1}} + adjective** — The thing is really that. Says really: zhēn goes before the describing word. On its own it is a whole sentence."],ru:["**Thing + {{word:zhen1}} + adjective** — Говорит «действительно»: zhēn стоит перед описывающим словом. Само по себе оно — целое предложение."],zh:[]},items:[{text:{en:["{{Word:zhen1}} {{word:re4}}! (It's really hot!)"],ru:["{{Word:zhen1}} {{word:re4}}!"],zh:[]}},{text:{en:["{{Word:ta1}} {{word:zhen1}} {{word:hao3}}. (She's really nice.)"],ru:["{{Word:ta1}} {{word:zhen1}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**Who + {{word:zhi3}} + verb** — Who only does the verb. Says only: zhǐ goes before the verb."],ru:["**Who + {{word:zhi3}} + verb** — Говорит «только»: zhǐ стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:zhi3}} {{word:yao4}} {{word:shui3}}. (I only want water.)"],ru:["{{Word:wo3}} {{word:zhi3}} {{word:yao4}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:zhi3}} {{word:you3}} {{word:yi1}}-{{light:ge4}}. (He only has one.)"],ru:["{{Word:ta1}} {{word:zhi3}} {{word:you3}} {{word:yi1}}-{{light:ge4}}."],zh:[]}}]},{text:{en:["**Thing + {{word:bu4}} + adjective** — The thing is not that. Says something is not so: bù goes before the describing word, with no hěn. Bù hěn means not very."],ru:["**Thing + {{word:bu4}} + adjective** — Говорит, что это не так: bù стоит перед описывающим словом, без hěn. Bù hěn значит «не очень»."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:bu4}} {{word:leng3}}. (The water isn't cold.)"],ru:["{{Word:shui3}} {{word:bu4}} {{word:leng3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:de}} {{word:shou3}} {{word:bu4}} {{word:gan1jing4}}. (My hands are dirty.)"],ru:["{{Word:wo3}} {{word:de}} {{word:shou3}} {{word:bu4}} {{word:gan1jing4}}."],zh:[]}}]},{text:{en:["**Who + (adverb) + {{word:mei2}}-{{word:you3}} (+ thing)** — Who doesn't have (the thing), maybe often or rarely. Méi yǒu can stand with nothing after it: wǒ méi yǒu, I don't have any. And hěn and a describing word can go before it, as before any verb: wǒ hěn shǎo méi yǒu shuǐ, I rarely have no water."],ru:["**Who + (adverb) + {{word:mei2}}-{{word:you3}} (+ thing)** — Méi yǒu может стоять и без того, что за ним: wǒ méi yǒu — у меня нет. А hěn и описывающее слово могут стоять перед ним, как перед любым глаголом: wǒ hěn shǎo méi yǒu shuǐ — у меня редко нет воды."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:mei2}} {{word:you3}}. (I don't have any.)"],ru:["{{Word:wo3}} {{word:mei2}} {{word:you3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:hen3}} {{word:shao3}} {{word:mei2}} {{word:you3}} {{word:shui3}}. (I rarely have no water.)"],ru:["{{Word:wo3}} {{word:hen3}} {{word:shao3}} {{word:mei2}} {{word:you3}} {{word:shui3}}."],zh:[]}}]},{text:{en:["**{{word:you3}}-{{word:xie1}} + noun** — Some of them. Yǒu-xiē before a noun means some: yǒu-xiē rén bù lái, some people aren't coming."],ru:["**{{word:you3}}-{{word:xie1}} + noun** — Yǒu-xiē перед существительным значит «некоторые»: yǒu-xiē rén bù lái — некоторые не придут."],zh:[]},items:[{text:{en:["{{Word:you3}}-{{word:xie1}} {{word:ren2}} {{word:bu4}} {{word:lai2}}. (Some people aren't coming.)"],ru:["{{Word:you3}}-{{word:xie1}} {{word:ren2}} {{word:bu4}} {{word:lai2}}."],zh:[]}}]},{text:{en:["**verb (+ object) + {{word:hen3}} + adjective** — Doing the verb is that. What someone does can be the topic of a sentence: xué-xiě bù nán, learning to write isn't hard."],ru:["**verb (+ object) + {{word:hen3}} + adjective** — То, что кто-то делает, может быть темой предложения: xué-xiě bù nán — учиться писать нетрудно."],zh:[]},items:[{text:{en:["{{Word:xue2}} {{word:xie3}} {{word:bu4}} {{word:nan2}}. (Learning to write isn't difficult.)"],ru:["{{Word:xue2}} {{word:xie3}} {{word:bu4}} {{word:nan2}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 13 · Modifiers 2 — Comparing"],zh:[],ru:["Урок 13 · Уточнения 2 — Сравнение"]},items:[{text:{en:["**A + {{word:bi3}} + B + adjective** — A is more than B. Says one thing is more than another: bǐ (than) goes between them, then the describing word, with no hěn."],ru:["**A + {{word:bi3}} + B + adjective** — Говорит, что одно больше другого: bǐ («чем») стоит между ними, потом описывающее слово, без hěn."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:bi3}} {{word:ni3}} {{word:da4}}. (I'm bigger than you.)"],ru:["{{Word:wo3}} {{word:bi3}} {{word:ni3}} {{word:da4}}."],zh:[]}},{text:{en:["{{Word:ren2}} {{word:bi3}} {{word:jin1}} {{word:you3}} {{word:jia4zhi2}}. (People are worth more than money.)"],ru:["{{Word:ren2}} {{word:bi3}} {{word:jin1}} {{word:you3}} {{word:jia4zhi2}}."],zh:[]}}]},{text:{en:["**A {{word:mei2}} {{word:you3}} B + adjective** — A is not as good as B. Méi yǒu before the other one and a describing word says not as good as: wǒ méi yǒu tā hǎo, I am not as good as him."],ru:["**A {{word:mei2}} {{word:you3}} B + adjective** — Méi yǒu перед другим и описанием значит «не так … как»: wǒ méi yǒu tā hǎo — я не так хорош, как он."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:mei2}} {{word:you3}} {{word:na4}}-{{word:ge4}} {{word:hao3}}. (This one is not as good as that one.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:mei2}} {{word:you3}} {{word:na4}}-{{word:ge4}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**Thing + {{word:zui4}} + adjective** — The thing is the most that. Says the most: zuì goes before the describing word or the verb. Zuì-hòu is last."],ru:["**Thing + {{word:zui4}} + adjective** — Говорит «самый»: zuì стоит перед описывающим словом или глаголом. Zuì-hòu значит «последний»."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:zui4}} {{word:da4}}. (This one is the biggest.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:zui4}} {{word:da4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:zui4}} {{word:ai4}} {{word:zhi2wu4}}. (I love plants the most.)"],ru:["{{Word:wo3}} {{word:zui4}} {{word:ai4}} {{word:zhi2wu4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:zui4}}-{{word:hou4}} {{word:lai2}}. (He came last.)"],ru:["{{Word:ta1}} {{word:zui4}}-{{word:hou4}} {{word:lai2}}."],zh:[]}}]},{text:{en:["**Things + {{word:yi1}}-{{word:yang4}}** — The things are the same. Says things are the same: yī-yàng goes after the things. Bù yī-yàng says they differ."],ru:["**Things + {{word:yi1}}-{{word:yang4}}** — Говорит, что вещи одинаковы: yī-yàng стоит после вещей. Bù yī-yàng говорит, что они разные."],zh:[]},items:[{text:{en:["{{Word:ta1}}-{{word:men}} {{word:yi1}}-{{word:yang4}}. (They're the same.)"],ru:["{{Word:ta1}}-{{word:men}} {{word:yi1}}-{{word:yang4}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:di4}}-{{light:fang1}} {{word:hen3}} {{word:bu4}} {{word:yi1}}-{{word:yang4}}. (This place is very different.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:di4}}-{{light:fang1}} {{word:hen3}} {{word:bu4}} {{word:yi1}}-{{word:yang4}}."],zh:[]}}]},{text:{en:["**{{word:da4}}-{{word:xiao3}}** — The size. Dà and xiǎo together name the size: nǐ shēntǐ de dà-xiǎo, the size of your body."],ru:["**{{word:da4}}-{{word:xiao3}}** — Dà и xiǎo вместе называют размер: nǐ shēntǐ de dà-xiǎo — размер твоего тела."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:bu4}} {{word:zhi1dao4}} {{word:wo3}} {{word:shen1ti3}} {{word:de}} {{word:da4}}-{{word:xiao3}}. (I don't know the size of my body.)"],ru:["{{Word:wo3}} {{word:bu4}} {{word:zhi1dao4}} {{word:wo3}} {{word:shen1ti3}} {{word:de}} {{word:da4}}-{{word:xiao3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 14 · Modifiers 3 — Also and all"],zh:[],ru:["Урок 14 · Уточнения 3 — Тоже и все"]},items:[{text:{en:["**Sentence, sentence** — One thing, and another. Two sentences can be joined with a comma: this one is cold, and that one too."],ru:["**Sentence, sentence** — Два предложения можно соединить запятой: это холодное, и то тоже."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:hen3}} {{word:leng3}}, {{word:ta1}} {{word:ye3}} {{word:hen3}} {{word:leng3}}. (I'm cold, and he's cold too.)"],ru:["{{Word:wo3}} {{word:hen3}} {{word:leng3}}, {{word:ta1}} {{word:ye3}} {{word:hen3}} {{word:leng3}}."],zh:[]}}]},{text:{en:["**Who + {{word:ye3}} + verb** — Who also does the verb. Says someone also does it: yě goes right before the verb, after the doer. It also goes before hěn."],ru:["**Who + {{word:ye3}} + verb** — Говорит, что кто-то тоже это делает: yě стоит прямо перед глаголом, после того, кто делает. Оно стоит и перед hěn."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ye3}} {{word:chi1}}. (I eat too.)"],ru:["{{Word:wo3}} {{word:ye3}} {{word:chi1}}."],zh:[]}},{text:{en:["{{Word:kong1}}-{{word:qi4}} {{word:ye3}} {{word:hen3}} {{word:leng3}}. (The air is cold too.)"],ru:["{{Word:kong1}}-{{word:qi4}} {{word:ye3}} {{word:hen3}} {{word:leng3}}."],zh:[]}}]},{text:{en:["**Who + {{word:hai2}} + verb** — Who still does the verb. Says something is still so, or there is more: hái goes before the verb."],ru:["**Who + {{word:hai2}} + verb** — Говорит, что это всё ещё так, или что есть ещё: hái стоит перед глаголом."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:hai2}} {{word:zai4}} {{word:jia1}}. (He's still at home.)"],ru:["{{Word:ta1}} {{word:hai2}} {{word:zai4}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:hai2}} {{word:yao4}} {{word:ma}}? (Do you want more?)"],ru:["{{Word:ni3}} {{word:hai2}} {{word:yao4}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**People or things + {{word:dou1}} + verb** — All of them do the verb. Says they all do it: dōu goes right before the verb, after the people or things. It never goes before a noun."],ru:["**People or things + {{word:dou1}} + verb** — Говорит, что все это делают: dōu стоит прямо перед глаголом, после людей или вещей. Перед существительным оно не стоит."],zh:[]},items:[{text:{en:["{{Word:wo3}}-{{word:men}} {{word:dou1}} {{word:chi1}}. (We all eat.)"],ru:["{{Word:wo3}}-{{word:men}} {{word:dou1}} {{word:chi1}}."],zh:[]}},{text:{en:["{{Word:shui3}} {{word:dou1}} {{word:he1}}-{{word:wan2}} {{word:le}}. (The water is all gone.)"],ru:["{{Word:shui3}} {{word:dou1}} {{word:he1}}-{{word:wan2}} {{word:le}}."],zh:[]}}]},{text:{en:["**Who + {{word:yi4qi3}} + verb** — Who does the verb together. Yìqǐ before a verb says it is done together: wǒ-men yìqǐ chī, we eat together."],ru:["**Who + {{word:yi4qi3}} + verb** — Yìqǐ перед глаголом говорит, что это делают вместе: wǒ-men yìqǐ chī — мы едим вместе."],zh:[]},items:[{text:{en:["{{Word:wo3}}-{{word:men}} {{word:yi4qi3}} {{word:chi1}}. (We eat together.)"],ru:["{{Word:wo3}}-{{word:men}} {{word:yi4qi3}} {{word:chi1}}."],zh:[]}}]},{text:{en:["**Who + {{word:shen2me}}-{{word:dou1}} + verb** — Who does the verb to everything. Says everything: shénme-dōu goes before the verb. With bù or méi it means nothing."],ru:["**Who + {{word:shen2me}}-{{word:dou1}} + verb** — Говорит «всё»: shénme-dōu стоит перед глаголом. С bù или méi оно значит «ничего»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:shen2me}} {{word:dou1}} {{word:chi1}}. (I eat everything.)"],ru:["{{Word:wo3}} {{word:shen2me}} {{word:dou1}} {{word:chi1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:shen2me}} {{word:dou1}} {{word:bu4}} {{word:yao4}}. (I don't want anything.)"],ru:["{{Word:wo3}} {{word:shen2me}} {{word:dou1}} {{word:bu4}} {{word:yao4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:shen2me}} {{word:dou1}} {{word:mei2}} {{word:kan4}}-{{word:dao4}}. (He didn't see anything.)"],ru:["{{Word:ta1}} {{word:shen2me}} {{word:dou1}} {{word:mei2}} {{word:kan4}}-{{word:dao4}}."],zh:[]}}]},{text:{en:["**{{word:zhe4}} / {{word:na4}} / {{word:da4}} + {{word:bu4}}-{{word:fen1}}** — This / that / the big part. Says part of something: bùfen follows zhè, nà or dà. Dà bùfen before a noun means most of them."],ru:["**{{word:zhe4}} / {{word:na4}} / {{word:da4}} + {{word:bu4}}-{{word:fen1}}** — Говорит о части чего-то: bùfen стоит после zhè, nà или dà. Dà bùfen перед существительным значит «большинство»."],zh:[]},items:[{text:{en:["{{Word:zhe4}} {{word:bu4}}-{{word:fen1}} {{word:hen3}} {{word:hao3}}. (This part is good.)"],ru:["{{Word:zhe4}} {{word:bu4}}-{{word:fen1}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:da4}} {{word:bu4}}-{{word:fen1}} {{word:ren2}} {{word:ai4}} {{word:dong4}}-{{word:wu4}}. (Most people love animals.)"],ru:["{{Word:da4}} {{word:bu4}}-{{word:fen1}} {{word:ren2}} {{word:ai4}} {{word:dong4}}-{{word:wu4}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 15 · Modifiers 4 — Becoming and making"],zh:[],ru:["Урок 15 · Уточнения 4 — Становиться и делать"]},items:[{text:{en:["**Thing + adjective + {{word:le}}** — The thing became that. Says something changed: le goes after the describing word, with no hěn."],ru:["**Thing + adjective + {{word:le}}** — Говорит, что что-то изменилось: le стоит после описывающего слова, без hěn."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:re4}} {{word:le}}. (The water got hot.)"],ru:["{{Word:shui3}} {{word:re4}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:hao3}} {{word:le}}. (It's better now.)"],ru:["{{Word:hao3}} {{word:le}}."],zh:[]}}]},{text:{en:["**Thing + {{word:bian4}} + adjective + {{word:le}}** — The thing turned that. Says something became different: biàn goes before the describing word, and le after it."],ru:["**Thing + {{word:bian4}} + adjective + {{word:le}}** — Говорит, что что-то стало другим: biàn стоит перед описывающим словом, а le после него."],zh:[]},items:[{text:{en:["{{Word:shui3}} {{word:bian4}} {{word:leng3}} {{word:le}}. (The water turned cold.)"],ru:["{{Word:shui3}} {{word:bian4}} {{word:leng3}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:bian4}} {{word:hao3}} {{word:le}}. (He got better.)"],ru:["{{Word:ta1}} {{word:bian4}} {{word:hao3}} {{word:le}}."],zh:[]}}]},{text:{en:["**{{word:rang4}} + who + describing word / verb** — Make or let them be so / do it. Ràng and someone says make or let them: ràng shǒu gānjìng, make the hands clean; ràng tā lái, let him come."],ru:["**{{word:rang4}} + who + describing word / verb** — Ràng и кто-то значат «сделать так, чтобы» или «позволить»: ràng shǒu gānjìng — сделать руки чистыми; ràng tā lái — пусть он придёт."],zh:[]},items:[{text:{en:["{{Word:yong4}} {{word:shui3}} {{word:rang4}} {{word:shou3}} {{word:gan1jing4}}. (Wash your hands.)"],ru:["{{Word:yong4}} {{word:shui3}} {{word:rang4}} {{word:shou3}} {{word:gan1jing4}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:zhen1}} {{word:rang4}} {{word:ren2}} {{word:kai1}}-{{word:xin1}}. (This really makes people happy.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:zhen1}} {{word:rang4}} {{word:ren2}} {{word:kai1}}-{{word:xin1}}."],zh:[]}}]},{text:{en:["**Who + {{word:zuo4}} + result** — Who makes it so. Says you make something so: zuò goes before the result. Zuò hǎo is fix it, zuò huài is break it."],ru:["**Who + {{word:zuo4}} + result** — Говорит, что вы делаете что-то таким: zuò стоит перед результатом. Zuò hǎo — «починить», zuò huài — «сломать»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:zuo4}} {{word:hao3}} {{word:le}}. (I fixed it.)"],ru:["{{Word:wo3}} {{word:zuo4}} {{word:hao3}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:neng2}} {{word:zuo4}} {{word:hao3}} {{word:ma}}? (Can you fix it?)"],ru:["{{Word:ni3}} {{word:neng2}} {{word:zuo4}} {{word:hao3}} {{word:ma}}?"],zh:[]}}]},{text:{en:["**Who + {{word:ba3}} + thing + {{word:zuo4}} + result** — Who does the verb to the thing. Says what you do to a thing: bǎ and the thing come before the action, which ends in a result."],ru:["**Who + {{word:ba3}} + thing + {{word:zuo4}} + result** — Говорит, что вы делаете с вещью: bǎ и вещь стоят перед действием, которое заканчивается результатом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ba3}} {{word:gong1}}-{{word:ju4}} {{word:zuo4}} {{word:hao3}} {{word:le}}. (I fixed the tool.)"],ru:["{{Word:wo3}} {{word:ba3}} {{word:gong1}}-{{word:ju4}} {{word:zuo4}} {{word:hao3}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:ba3}} {{word:deng1}} {{word:guan1}} {{word:le}}. (Turn off the light.)"],ru:["{{Word:ba3}} {{word:deng1}} {{word:guan1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:ba3}} {{word:yi1fu}} {{word:fang4}} {{word:zai4}} {{word:di4}}-{{word:shang4}} {{word:le}}. (I put the clothes on the floor.)"],ru:["{{Word:wo3}} {{word:ba3}} {{word:yi1fu}} {{word:fang4}} {{word:zai4}} {{word:di4}}-{{word:shang4}} {{word:le}}."],zh:[]}}]},{text:{en:["**Who + {{word:ba3}} + thing + describing word** — Who makes the thing so. Says what you make a thing be: bǎ, the thing, then a describing word for how it ends up (make the room clean)."],ru:["**Who + {{word:ba3}} + thing + describing word** — Говорит, какой вы делаете вещь: bǎ, вещь, затем слово-описание того, какой она станет (сделать комнату чистой)."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ba3}} {{word:fang2}}-{{word:jian1}} {{word:gan1jing4}}. (I make the room clean.)"],ru:["{{Word:wo3}} {{word:ba3}} {{word:fang2}}-{{word:jian1}} {{word:gan1jing4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:ba3}} {{word:yi1fu}} {{word:gan1jing4}}. (She makes the clothes clean.)"],ru:["{{Word:ta1}} {{word:ba3}} {{word:yi1fu}} {{word:gan1jing4}}."],zh:[]}}]},{text:{en:["**{{word:li4}}-{{word:qi4}}** — Strength. Lì-qì, strength-air, is the strength of a body: tā hěn yǒu lì-qì, he is very strong."],ru:["**{{word:li4}}-{{word:qi4}}** — Lì-qì («сила-воздух») — сила тела: tā hěn yǒu lì-qì — он очень сильный."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:hen3}} {{word:you3}} {{word:li4}}-{{word:qi4}}. (He is very strong.)"],ru:["{{Word:ta1}} {{word:hen3}} {{word:you3}} {{word:li4}}-{{word:qi4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:mei2}}-{{word:you3}} {{word:li4}}-{{word:qi4}}. (I have no strength.)"],ru:["{{Word:wo3}} {{word:mei2}}-{{word:you3}} {{word:li4}}-{{word:qi4}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 16 · Verbs 2 — Direction and result"],zh:[],ru:["Урок 16 · Глаголы 2 — Направление и результат"]},items:[{text:{en:["**Who + verb-result** — Who does the verb through to the result. Says how an action ends: a result word joins the verb, like kàn-dào (see), zuò-hǎo (fix) or xué-huì (learn until you can)."],ru:["**Who + verb-result** — Говорит, чем кончается действие: к глаголу присоединяется слово-результат, например kàn-dào («увидеть»), zuò-hǎo («починить») или xué-huì («выучиться»)."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:xue2}}-{{word:hui4}} {{word:le}} {{word:ma}}? (Have you learned how?)"],ru:["{{Word:ni3}} {{word:xue2}}-{{word:hui4}} {{word:le}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:wo3}} {{word:kan4}}-{{word:jian4}} {{word:ta1}} {{word:le}}. (I saw him.)"],ru:["{{Word:wo3}} {{word:kan4}}-{{word:jian4}} {{word:ta1}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:mei2}} {{word:zhao3}}-{{word:dao4}}. (I didn't find it.)"],ru:["{{Word:wo3}} {{word:mei2}} {{word:zhao3}}-{{word:dao4}}."],zh:[]}}]},{text:{en:["**verb-{{word:de}}-result / verb-{{word:bu4}}-result** — Can / can't get the result. Says you can or can't get the result: dé (can) or bù (can't) goes between the verb and the result."],ru:["**verb-{{word:de}}-result / verb-{{word:bu4}}-result** — Говорит, можно ли достичь результата: de («можно») или bù («нельзя») стоит между глаголом и результатом."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:ting1}} {{word:de}} {{word:dao4}} {{word:ma}}? (Can you hear it?)"],ru:["{{Word:ni3}} {{word:ting1}} {{word:de}} {{word:dao4}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:wo3}} {{word:he1}} {{word:bu4}} {{word:wan2}}. (I can't finish drinking it.)"],ru:["{{Word:wo3}} {{word:he1}} {{word:bu4}} {{word:wan2}}."],zh:[]}}]},{text:{en:["**Thing + adjective-{{word:qi3}}-{{word:lai2}}** — The thing starts to get that way. Says something starts to get that way: qǐ-lái goes after the describing word. After a verb it says how a thing seems when you look, taste or hear it: kàn-qǐ-lái hěn hǎo, it looks good. Xià-qù after a verb says keep going."],ru:["**Thing + adjective-{{word:qi3}}-{{word:lai2}}** — Говорит, что что-то начинает становиться таким: qǐ-lái стоит после описывающего слова. После глагола оно говорит, каким предмет кажется на вид, вкус или слух: kàn-qǐ-lái hěn hǎo — выглядит хорошо. Xià-qù после глагола значит «продолжай»."],zh:[]},items:[{text:{en:["{{Word:kong1}}-{{word:qi4}} {{word:leng3}}-{{word:qi3}}-{{word:lai2}} {{word:le}}. (It's getting cold.)"],ru:["{{Word:kong1}}-{{word:qi4}} {{word:leng3}}-{{word:qi3}}-{{word:lai2}} {{word:le}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:zhi2wu4}} {{word:kan4}}-{{word:qi3}}-{{word:lai2}} {{word:hen3}} {{word:hao3}}. (This plant looks good.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:zhi2wu4}} {{word:kan4}}-{{word:qi3}}-{{word:lai2}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:shuo1}}-{{word:xia4}}-{{word:qu4}}! (Keep talking!)"],ru:["{{Word:ni3}} {{word:shuo1}}-{{word:xia4}}-{{word:qu4}}!"],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 17 · Numbers"],zh:[],ru:["Урок 17 · Числа"]},items:[{text:{en:["**number, number, number …** — Counting out loud. Numbers can be said in a row, with commas, and can stand as things themselves: sān bǐ èr duō, three is more than two."],ru:["**number, number, number …** — Числа можно называть подряд, через запятую, и они могут быть самостоятельными вещами: sān bǐ èr duō — три больше двух."],zh:[]},items:[{text:{en:["{{Word:yi1}}, {{word:er4}}, {{word:san1}}! (One, two, three!)"],ru:["{{Word:yi1}}, {{word:er4}}, {{word:san1}}!"],zh:[]}},{text:{en:["{{Word:san1}} {{word:bi3}} {{word:er4}} {{word:duo1}}. (Three is more than two.)"],ru:["{{Word:san1}} {{word:bi3}} {{word:er4}} {{word:duo1}}."],zh:[]}},{text:{en:["{{Word:shi2}} {{word:zui4}} {{word:da4}}. (Ten is the biggest.)"],ru:["{{Word:shi2}} {{word:zui4}} {{word:da4}}."],zh:[]}}]},{text:{en:["**number + {{word:zhong3}} / {{word:ci4}} / {{word:bu4}}-{{word:fen1}}** — A number of kinds, times or parts. To count kinds, times or parts, put the number before zhǒng, cì or bù-fēn instead of gè: sān-zhǒng, three kinds; yī bù-fēn rén, some of the people."],ru:["**number + {{word:zhong3}} / {{word:ci4}} / {{word:bu4}}-{{word:fen1}}** — Чтобы считать виды, разы или части, поставьте число перед zhǒng, cì или bù-fēn вместо gè: sān-zhǒng — три вида; yī bù-fēn rén — часть людей."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:yao4}} {{word:yi1}} {{word:bu4}}-{{word:fen1}}. (I want one part.)"],ru:["{{Word:wo3}} {{word:yao4}} {{word:yi1}} {{word:bu4}}-{{word:fen1}}."],zh:[]}},{text:{en:["{{Word:yi1}} {{word:bu4}}-{{word:fen1}} {{word:ren2}} {{word:qu4}} {{word:le}}. (Some of the people went.)"],ru:["{{Word:yi1}} {{word:bu4}}-{{word:fen1}} {{word:ren2}} {{word:qu4}} {{word:le}}."],zh:[]}}]},{text:{en:["**{{word:shi2}} + number (11-19) / number + {{word:shi2}} (20, 30 …)** — A number above ten. Numbers above ten: shí goes before the other number for 11 to 19 (shí-èr) and after it for 20, 30 … (èr-shí). Past ninety-nine, say the digits one by one (yī-líng-líng, 100)."],ru:["**{{word:shi2}} + number (11-19) / number + {{word:shi2}} (20, 30 …)** — Числа больше десяти: shí стоит перед другим числом для 11–19 (shí-èr) и после него для 20, 30 … (èr-shí). После 99 называют цифры по одной (yī-líng-líng — 100)."],zh:[]},items:[{text:{en:["{{Word:shi2}}-{{word:yi1}}-{{light:ge4}} {{word:ren2}}. (Eleven people.)"],ru:["{{Word:shi2}}-{{word:yi1}}-{{light:ge4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:er4}}-{{word:shi2}}-{{light:ge4}} {{word:ren2}}. (Twenty people.)"],ru:["{{Word:er4}}-{{word:shi2}}-{{light:ge4}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:er4}}-{{word:ling2}}-{{word:ling2}}. (Two hundred.)"],ru:["{{Word:er4}}-{{word:ling2}}-{{word:ling2}}."],zh:[]}}]},{text:{en:["**number + {{word:hao4}}** — Number … (a thing named by its number). A number followed by hào names something by its number: èr-hào, number two. Dì before a number makes it an order: dì-yī, first."],ru:["**number + {{word:hao4}}** — Число и hào называют вещь по номеру: èr-hào — номер два. Dì перед числом задаёт порядок: dì-yī — первый."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:de}} {{word:jia1}} {{word:shi4}} {{word:wu3}} {{word:hao4}}. (My home is number five.)"],ru:["{{Word:wo3}} {{word:de}} {{word:jia1}} {{word:shi4}} {{word:wu3}} {{word:hao4}}."],zh:[]}},{text:{en:["{{Word:liu4}} {{word:hao4}} {{word:lu4}} {{word:tong1}} {{word:dao4}} {{word:wo3}} {{word:de}} {{word:jia1}}. (Road number six leads to my home.)"],ru:["{{Word:liu4}} {{word:hao4}} {{word:lu4}} {{word:tong1}} {{word:dao4}} {{word:wo3}} {{word:de}} {{word:jia1}}."],zh:[]}}]},{text:{en:["**{{word:qian2}} / {{word:hou4}} + number + measure word + span** — The span before / after. Qián and hòu before a counted span of time name the one before or after: qián yī-ge rì is the day before, hòu shí-èr-ge yuè the twelve months after."],ru:["**{{word:qian2}} / {{word:hou4}} + number + measure word + span** — Qián и hòu перед посчитанным промежутком времени называют предыдущий или следующий: qián yī-ge rì — день до, hòu shí-èr-ge yuè — двенадцать месяцев после."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:qian2}} {{word:yi1}}-{{light:ge4}} {{word:ri4}} {{word:zai4}} {{word:jia1}}. (The day before, I was at home.)"],ru:["{{Word:wo3}} {{word:qian2}} {{word:yi1}}-{{light:ge4}} {{word:ri4}} {{word:zai4}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:hou4}} {{word:shi2}}-{{word:er4}}-{{light:ge4}} {{word:yue4}} {{word:wo3}} {{word:hui2}} {{word:jia1}}. (In the twelve months after, I go home.)"],ru:["{{Word:hou4}} {{word:shi2}}-{{word:er4}}-{{light:ge4}} {{word:yue4}} {{word:wo3}} {{word:hui2}} {{word:jia1}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 18 · Numbers 2 — Time and sums"],zh:[],ru:["Урок 18 · Числа 2 — Время и вычисления"]},items:[{text:{en:["**number + {{word:dian3}}** — The time of day. A number and diǎn says the hour, and goes before the verb: wǒ sān diǎn huí jiā. An evening or a morning can come first: wǎn-shàng qī diǎn."],ru:["**number + {{word:dian3}}** — Число и diǎn называют час и стоят перед глаголом: wǒ sān diǎn huí jiā. Вечер или утро могут идти раньше: wǎn-shàng qī diǎn."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:san1}} {{word:dian3}} {{word:hui2}} {{word:jia1}}. (I go home at three.)"],ru:["{{Word:wo3}} {{word:san1}} {{word:dian3}} {{word:hui2}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:shi2}}-{{word:er4}} {{word:dian3}} {{word:chi1}} {{word:fan4}}. (I eat at twelve o'clock.)"],ru:["{{Word:wo3}} {{word:shi2}}-{{word:er4}} {{word:dian3}} {{word:chi1}} {{word:fan4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:wan3}}-{{word:shang4}} {{word:qi1}} {{word:dian3}} {{word:chi1}} {{word:fan4}}. (I eat at seven in the evening.)"],ru:["{{Word:wo3}} {{word:wan3}}-{{word:shang4}} {{word:qi1}} {{word:dian3}} {{word:chi1}} {{word:fan4}}."],zh:[]}}]},{text:{en:["**{{word:ni3}} {{word:hao3}}!** — Hello! A greeting is someone and hǎo: nǐ hǎo, hello; nǐ-men hǎo, hello to you all; xīn-nián hǎo, happy New Year."],ru:["**{{word:ni3}} {{word:hao3}}!** — Приветствие — это кто-то и hǎo: nǐ hǎo — здравствуй; nǐ-men hǎo — здравствуйте всем; xīn-nián hǎo — с Новым годом."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:hao3}}! (Hello!)"],ru:["{{Word:ni3}} {{word:hao3}}!"],zh:[]}},{text:{en:["{{Word:ni3}}-{{word:men}} {{word:hao3}}! (Hello, everyone!)"],ru:["{{Word:ni3}}-{{word:men}} {{word:hao3}}!"],zh:[]}},{text:{en:["{{Word:xin1}}-{{word:nian2}} {{word:hao3}}! (Happy New Year!)"],ru:["{{Word:xin1}}-{{word:nian2}} {{word:hao3}}!"],zh:[]}}]},{text:{en:["**number + {{word:tian1}} / {{word:nian2}}** — A number of days or years. A number goes right before tiān (day) or nián (year), with no gè: sān tiān, three days. How long an action lasts goes after the verb. Míng-tiān (tomorrow), hòu-tiān, qù-nián (last year), míng-nián are times that go first."],ru:["**number + {{word:tian1}} / {{word:nian2}}** — Число стоит прямо перед tiān («день») или nián («год»), без gè: sān tiān — три дня. Сколько длится действие — после глагола. Míng-tiān («завтра»), hòu-tiān, qù-nián («прошлый год»), míng-nián — это время, оно идёт первым."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:deng3}} {{word:le}} {{word:san1}} {{word:tian1}}. (I waited three days.)"],ru:["{{Word:wo3}} {{word:deng3}} {{word:le}} {{word:san1}} {{word:tian1}}."],zh:[]}},{text:{en:["{{Word:yi1}} {{word:nian2}} {{word:you3}} {{word:shi2}}-{{word:er4}} {{light:ge4}} {{word:yue4}}. (A year has twelve months.)"],ru:["{{Word:yi1}} {{word:nian2}} {{word:you3}} {{word:shi2}}-{{word:er4}} {{light:ge4}} {{word:yue4}}."],zh:[]}},{text:{en:["{{Word:ming2}}-{{word:tian1}} {{word:wo3}} {{word:hui2}} {{word:jia1}}. (I'll go home tomorrow.)"],ru:["{{Word:ming2}}-{{word:tian1}} {{word:wo3}} {{word:hui2}} {{word:jia1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:qian2}}-{{word:yi1}}-{{word:tian1}} {{word:qu4}} {{word:le}}. (I went yesterday.)"],ru:["{{Word:wo3}} {{word:qian2}}-{{word:yi1}}-{{word:tian1}} {{word:qu4}} {{word:le}}."],zh:[]}}]},{text:{en:["**Person + number** — The person is that old. A number alone can say a number: jīn-nián wǒ èr-shí, this year I am twenty."],ru:["**Person + number** — Число само по себе может быть сказуемым: jīn-nián wǒ èr-shí — в этом году мне двадцать."],zh:[]},items:[{text:{en:["{{Word:jin1}}-{{word:nian2}} {{word:wo3}} {{word:er4}}-{{word:shi2}}. (I'm twenty this year.)"],ru:["{{Word:jin1}}-{{word:nian2}} {{word:wo3}} {{word:er4}}-{{word:shi2}}."],zh:[]}}]},{text:{en:["**adjective + {{word:yi1}}-{{word:dian3}} / {{word:you3}} {{word:yi1}}-{{word:dian3}} + adjective** — A bit more / a bit. Yī diǎn says a little. After a describing word it is a bit more (dà yī diǎn); after yǒu, before a describing word, it is a bit (yǒu yī diǎn lěng); after a verb it is a little of it (chī yī diǎn)."],ru:["**adjective + {{word:yi1}}-{{word:dian3}} / {{word:you3}} {{word:yi1}}-{{word:dian3}} + adjective** — Yī diǎn значит «немного». После описывающего слова — чуть больше (dà yī diǎn); после yǒu и перед описывающим словом — «чуть-чуть» (yǒu yī diǎn lěng); после глагола — «немного» (chī yī diǎn)."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:da4}} {{word:yi1}} {{word:dian3}}. (This one is a bit bigger.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:da4}} {{word:yi1}} {{word:dian3}}."],zh:[]}},{text:{en:["{{Word:shui3}} {{word:you3}} {{word:yi1}} {{word:dian3}} {{word:leng3}}. (The water is a bit cold.)"],ru:["{{Word:shui3}} {{word:you3}} {{word:yi1}} {{word:dian3}} {{word:leng3}}."],zh:[]}},{text:{en:["{{Word:duo1}} {{word:chi1}} {{word:yi1}} {{word:dian3}}! (Eat a bit more!)"],ru:["{{Word:duo1}} {{word:chi1}} {{word:yi1}} {{word:dian3}}!"],zh:[]}}]},{text:{en:["**number + {{word:jin1}}** — That much money. A number and jīn says how much money: shí jīn, ten; hěn shǎo jīn, very little money."],ru:["**number + {{word:jin1}}** — Число и jīn говорят, сколько денег: shí jīn — десять; hěn shǎo jīn — очень мало денег."],zh:[]},items:[{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:yao4}} {{word:yi1}} {{word:ling2}} {{word:ling2}} {{word:jin1}}. (This costs a hundred.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:yao4}} {{word:yi1}} {{word:ling2}} {{word:ling2}} {{word:jin1}}."],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:yao4}} {{word:hen3}} {{word:shao3}} {{word:jin1}}. (This is cheap.)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:yao4}} {{word:hen3}} {{word:shao3}} {{word:jin1}}."],zh:[]}}]},{text:{en:["**A, B {{word:fang4}} {{word:zai4}} {{word:yi4qi3}}, {{word:shi4}} C** — A and B put together is C. To add, put the numbers together (fàng zài yìqǐ). To take away, use ná. The answer comes after a comma with shì: shì qī, it's seven."],ru:["**A, B {{word:fang4}} {{word:zai4}} {{word:yi4qi3}}, {{word:shi4}} C** — Чтобы сложить, соедините числа (fàng zài yìqǐ). Чтобы вычесть, используйте ná. Ответ идёт после запятой с shì: shì qī — «получается семь»."],zh:[]},items:[{text:{en:["{{Word:san1}}, {{word:si4}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}}, {{word:shi4}} {{word:qi1}}. (Three and four put together is seven.)"],ru:["{{Word:san1}}, {{word:si4}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}}, {{word:shi4}} {{word:qi1}}."],zh:[]}},{text:{en:["{{Word:cong2}} {{word:qi1}} {{word:li3}}-{{word:mian4}} {{word:na2}} {{word:san1}}, {{word:shi4}} {{word:si4}}. (Take three from seven, and it's four.)"],ru:["{{Word:cong2}} {{word:qi1}} {{word:li3}}-{{word:mian4}} {{word:na2}} {{word:san1}}, {{word:shi4}} {{word:si4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:suan4}} {{word:le}}, {{word:shi4}} {{word:qi1}}. (I worked it out: it's seven.)"],ru:["{{Word:wo3}} {{word:suan4}} {{word:le}}, {{word:shi4}} {{word:qi1}}."],zh:[]}}]},{text:{en:["**{{word:ba3}} A {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} B-{{word:ci4}}, {{word:shi4}} C** — A put together B times is C. To multiply, put a number together many times (fàng zài yìqǐ sān cì). To divide, say how many times you can take it away (néng ná sān cì)."],ru:["**{{word:ba3}} A {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} B-{{word:ci4}}, {{word:shi4}} C** — Чтобы умножить, соедините число много раз (fàng zài yìqǐ sān cì). Чтобы разделить, скажите, сколько раз можно его взять (néng ná sān cì)."],zh:[]},items:[{text:{en:["{{Word:ba3}} {{word:si4}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} {{word:san1}} {{word:ci4}}, {{word:shi4}} {{word:shi2}}-{{word:er4}}. (Four put together three times is twelve.)"],ru:["{{Word:ba3}} {{word:si4}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} {{word:san1}} {{word:ci4}}, {{word:shi4}} {{word:shi2}}-{{word:er4}}."],zh:[]}},{text:{en:["{{Word:ba3}} {{word:wu3}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} {{word:liang3}} {{word:ci4}}, {{word:shi4}} {{word:shi2}}. (Five put together twice is ten.)"],ru:["{{Word:ba3}} {{word:wu3}} {{word:fang4}} {{word:zai4}} {{word:yi4qi3}} {{word:liang3}} {{word:ci4}}, {{word:shi4}} {{word:shi2}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 19 · Colors"],zh:[],ru:["Урок 19 · Цвета"]},items:[{text:{en:["**Thing + {{word:shi4}} + {{word:shen2me}} {{word:yan2se4}}?** — What color is the thing? Shénme yánsè asks what color: nǐ-de yīfu shì shénme yánsè? The answer is the color, then de."],ru:["**Thing + {{word:shi4}} + {{word:shen2me}} {{word:yan2se4}}?** — Shénme yánsè спрашивает о цвете: nǐ-de yīfu shì shénme yánsè? В ответе — цвет и de."],zh:[]},items:[{text:{en:["{{Word:ni3}}-{{word:de}} {{word:yi1fu}} {{word:shi4}} {{word:shen2me}} {{word:yan2se4}}? (What color are your clothes?)"],ru:["{{Word:ni3}}-{{word:de}} {{word:yi1fu}} {{word:shi4}} {{word:shen2me}} {{word:yan2se4}}?"],zh:[]}},{text:{en:["{{Word:zhe4}}-{{light:ge4}} {{word:zhi2wu4}} {{word:shi4}} {{word:shen2me}} {{word:yan2se4}}? (What color is this plant?)"],ru:["{{Word:zhe4}}-{{light:ge4}} {{word:zhi2wu4}} {{word:shi4}} {{word:shen2me}} {{word:yan2se4}}?"],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 20 · Changing the Role of a Word"],zh:[],ru:["Урок 20 · Слово в новой роли"]},items:[{text:{en:["**verb-{{word:de}}** — The thing the verb is about. A verb with -de names the thing the action is about: chī-de is food, wǒ xiě de is what I wrote."],ru:["**verb-{{word:de}}** — Глагол с -de называет вещь, о которой идёт действие: chī-de — еда, wǒ xiě de — то, что я написал."],zh:[]},items:[{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:wo3}} {{word:xie3}} {{word:de}}. (This is what I wrote.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:wo3}} {{word:xie3}} {{word:de}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:chi1}} {{word:de}} {{word:shi4}} {{word:shui3}}-{{word:guo3}}. (What he's eating is fruit.)"],ru:["{{Word:ta1}} {{word:chi1}} {{word:de}} {{word:shi4}} {{word:shui3}}-{{word:guo3}}."],zh:[]}}]},{text:{en:["**verb-{{word:de}} {{word:ren2}}** — The one who does the verb. A verb with -de before a noun names the one or the thing that does it: xiě-de rén, the one who writes; wǒ xiě de shū, the book I wrote."],ru:["**verb-{{word:de}} {{word:ren2}}** — Глагол с -de перед существительным называет того или то, что это делает: xiě-de rén — пишущий; wǒ xiě de shū — книга, которую я написал."],zh:[]},items:[{text:{en:["{{Word:xie3}} {{word:de}} {{word:ren2}} {{word:hen3}} {{word:hao3}}. (The one who writes is good.)"],ru:["{{Word:xie3}} {{word:de}} {{word:ren2}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:ta1}} {{word:xie3}} {{word:de}} {{word:shu1}}. (I love the book he wrote.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:ta1}} {{word:xie3}} {{word:de}} {{word:shu1}}."],zh:[]}}]},{text:{en:["**Who + verb-{{word:de}} + adjective** — Who does the verb in that way. To say how someone does something, put -de after the verb and then a describing word: tā shuō de hǎo, he speaks well."],ru:["**Who + verb-{{word:de}} + adjective** — Чтобы сказать, как кто-то что-то делает, поставьте -de после глагола и затем описывающее слово: tā shuō de hǎo — он хорошо говорит."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:xie3}} {{word:de}} {{word:hen3}} {{word:hao3}}. (You write very well.)"],ru:["{{Word:ni3}} {{word:xie3}} {{word:de}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:shuo1}} {{word:de}} {{word:bi3}} {{word:wo3}} {{word:hao3}}. (He speaks better than me.)"],ru:["{{Word:ta1}} {{word:shuo1}} {{word:de}} {{word:bi3}} {{word:wo3}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**{{word:zhe4}} {{word:yang4}} + verb** — Do it this way. Zhè-yàng before a verb says in this way: nǐ zhè-yàng zuò, do it like this."],ru:["**{{word:zhe4}} {{word:yang4}} + verb** — Zhè-yàng перед глаголом значит «вот так»: nǐ zhè-yàng zuò — делай вот так."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:zhe4}} {{word:yang4}} {{word:zuo4}}. (Do it like this.)"],ru:["{{Word:ni3}} {{word:zhe4}} {{word:yang4}} {{word:zuo4}}."],zh:[]}}]},{text:{en:["**{{word:cong2}} place {{word:lai2}}-{{word:de}} {{word:zai4}} place-{{word:de}} kind-{{word:de}} color-{{word:de}} noun** — from where, where it is, what kind, what color: the noun. Describing parts stand before one noun in a set order, each with its own -de: where it comes from, where it goes, where it is, what it does, what kind it is, what color it is, then the noun."],ru:["**{{word:cong2}} place {{word:lai2}}-{{word:de}} {{word:zai4}} place-{{word:de}} kind-{{word:de}} color-{{word:de}} noun** — Описания стоят перед одним существительным в определённом порядке, у каждого свой -de: откуда оно, куда идёт, где находится, что делает, какое оно, какого цвета, и затем само существительное."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:ai4}} {{word:xiao3}}-{{word:de}} {{word:hong2}}-{{word:de}} {{word:bao1}}. (I love the small red bag.)"],ru:["{{Word:wo3}} {{word:ai4}} {{word:xiao3}}-{{word:de}} {{word:hong2}}-{{word:de}} {{word:bao1}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:zai4}}-{{word:shui3}}-{{word:li3}}-{{word:de}} {{word:xiao3}}-{{word:de}} {{word:dong4}}-{{word:wu4}}. (This is a small animal that is in the water.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:zai4}}-{{word:shui3}}-{{word:li3}}-{{word:de}} {{word:xiao3}}-{{word:de}} {{word:dong4}}-{{word:wu4}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:kan4}} {{word:cong2}}-{{word:jia1}}-{{word:lai2}}-{{word:de}} {{word:da4}}-{{word:de}} {{word:ren2}}. (Look at the big person who is coming from home.)"],ru:["{{Word:ni3}} {{word:kan4}} {{word:cong2}}-{{word:jia1}}-{{word:lai2}}-{{word:de}} {{word:da4}}-{{word:de}} {{word:ren2}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:kan4}} {{word:fei1}}-{{word:de}} {{word:hong2}}-{{word:de}} {{word:dong4}}-{{word:wu4}}. (I look at the red animal that flies.)"],ru:["{{Word:wo3}} {{word:kan4}} {{word:fei1}}-{{word:de}} {{word:hong2}}-{{word:de}} {{word:dong4}}-{{word:wu4}}."],zh:[]}}]},{text:{en:["**owner-{{word:de}} + part** — The owner's part. An owner right before its part says whose part it is, with or without -de: dòng-wù shēntǐ, the animal's body; tā shēntǐ-de wài-miàn, the outside of his body."],ru:["**owner-{{word:de}} + part** — Владелец прямо перед своей частью показывает, чья это часть, с -de или без него: dòng-wù shēntǐ — тело животного; tā shēntǐ-de wài-miàn — наружная сторона его тела."],zh:[]},items:[{text:{en:["{{Word:dong4}}-{{word:wu4}} {{word:shen1ti3}} {{word:de}} {{word:wai4}}-{{word:mian4}} {{word:hen3}} {{word:ying4}}. (The animal's skin is hard.)"],ru:["{{Word:dong4}}-{{word:wu4}} {{word:shen1ti3}} {{word:de}} {{word:wai4}}-{{word:mian4}} {{word:hen3}} {{word:ying4}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:shen1ti3}} {{word:de}} {{word:wai4}}-{{word:mian4}} {{word:shi4}} {{word:bai2}}-{{word:se4}} {{word:de}}. (The outside of his body is white.)"],ru:["{{Word:ta1}} {{word:shen1ti3}} {{word:de}} {{word:wai4}}-{{word:mian4}} {{word:shi4}} {{word:bai2}}-{{word:se4}} {{word:de}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 21 · Relationships 1 — Inside a sentence"],zh:[],ru:["Урок 21 · Связи 1 — Внутри предложения"]},items:[{text:{en:["**Who + {{word:gei3}} + person + thing** — Who gives the person the thing. Gěi is to give: the person first, then the thing. Before a verb, gěi means for or to: wǒ gěi nǐ xiě, I write to you."],ru:["**Who + {{word:gei3}} + person + thing** — Gěi — «давать»: сначала человек, потом вещь. Перед глаголом gěi значит «для» или «кому»: wǒ gěi nǐ xiě — я пишу тебе."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:gei3}} {{word:ni3}} {{word:shui3}}. (I give you water.)"],ru:["{{Word:wo3}} {{word:gei3}} {{word:ni3}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:gei3}} {{word:wo3}} {{word:yi1}} {{word:bu4}}-{{word:fen1}}. (He gives me part of it.)"],ru:["{{Word:ta1}} {{word:gei3}} {{word:wo3}} {{word:yi1}} {{word:bu4}}-{{word:fen1}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:gei3}} {{word:ni3}} {{word:xie3}}. (I write to you.)"],ru:["{{Word:wo3}} {{word:gei3}} {{word:ni3}} {{word:xie3}}."],zh:[]}}]},{text:{en:["**{{word:huan4}} + person + verb** — Now the person does it, in someone else's place. Huàn is to swap. Huàn, the person, then the verb: now that person does it, in someone else's place: wǒ bù qù, huàn tā qù, I won't go, he goes instead."],ru:["**{{word:huan4}} + person + verb** — Huàn — «менять». Huàn, человек, затем глагол — теперь это делает он, вместо другого: wǒ bù qù, huàn tā qù — я не пойду, пойдёт он."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:bu4}} {{word:qu4}}, {{word:huan4}} {{word:ta1}} {{word:qu4}}. (I won't go; he goes instead.)"],ru:["{{Word:wo3}} {{word:bu4}} {{word:qu4}}, {{word:huan4}} {{word:ta1}} {{word:qu4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:bu4}} {{word:shuo1}}, {{word:huan4}} {{word:ni3}} {{word:shuo1}}. (I won't say it; you say it.)"],ru:["{{Word:wo3}} {{word:bu4}} {{word:shuo1}}, {{word:huan4}} {{word:ni3}} {{word:shuo1}}."],zh:[]}}]},{text:{en:["**{{word:wei4}} + who + verb / {{word:wei4}}-{{word:le}} + reason, sentence** — Do it for someone / for the sake of. Wèi before a person and a verb says for whom: wǒ wèi nǐ zuò le fàn, I cooked for you. Wèi-le starts a reason for doing: wèi-le háizi, tā gōng-zuò, for his children he works."],ru:["**{{word:wei4}} + who + verb / {{word:wei4}}-{{word:le}} + reason, sentence** — Wèi перед человеком и глаголом говорит, для кого: wǒ wèi nǐ zuò le fàn — я приготовил для тебя. Wèi-le начинает цель: wèi-le háizi, tā gōng-zuò — ради детей он работает."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:wei4}} {{word:ni3}} {{word:zuo4}} {{word:le}} {{word:fan4}}. (I cooked for you.)"],ru:["{{Word:wo3}} {{word:wei4}} {{word:ni3}} {{word:zuo4}} {{word:le}} {{word:fan4}}."],zh:[]}},{text:{en:["{{Word:wei4}}-{{word:le}} {{word:hai2zi}}, {{word:ta1}} {{word:gong1}}-{{word:zuo4}}. (He works for his children.)"],ru:["{{Word:wei4}}-{{word:le}} {{word:hai2zi}}, {{word:ta1}} {{word:gong1}}-{{word:zuo4}}."],zh:[]}}]},{text:{en:["**{{word:he2}} + who + verb** — Do it with someone. Hé before a person and a verb says with whom it is done: hé wǒ yìqǐ wánr, play together with me."],ru:["**{{word:he2}} + who + verb** — Hé перед человеком и глаголом говорит, с кем это делают: hé wǒ yìqǐ wánr — играть вместе со мной."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:he2}} {{word:wo3}} {{word:yi4qi3}} {{word:wan2r}}. (He plays together with me.)"],ru:["{{Word:ta1}} {{word:he2}} {{word:wo3}} {{word:yi4qi3}} {{word:wan2r}}."],zh:[]}}]},{text:{en:["**Who + {{word:yong4}} + thing + verb** — Who does the verb with the thing. Yòng and a thing before a verb says what you do it with: wǒ yòng gōng-jù xiě, I write with a tool."],ru:["**Who + {{word:yong4}} + thing + verb** — Yòng и вещь перед глаголом говорят, чем это делают: wǒ yòng gōng-jù xiě — я пишу инструментом."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:yong4}} {{word:gong1}}-{{word:ju4}} {{word:xie3}}. (I write with a tool.)"],ru:["{{Word:wo3}} {{word:yong4}} {{word:gong1}}-{{word:ju4}} {{word:xie3}}."],zh:[]}}]},{text:{en:["**A {{word:hai2}}-{{word:shi4}} B** — A or B? Hái-shì gives a choice: A or B? It asks the other person to choose, so it comes in a question."],ru:["**A {{word:hai2}}-{{word:shi4}} B** — Hái-shì предлагает выбор: A или B? Оно просит собеседника выбрать, поэтому стоит в вопросе."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:yao4}} {{word:zhe4}}-{{light:ge4}} {{word:hai2}}-{{word:shi4}} {{word:na4}}-{{light:ge4}}? (Do you want this one or that one?)"],ru:["{{Word:ni3}} {{word:yao4}} {{word:zhe4}}-{{light:ge4}} {{word:hai2}}-{{word:shi4}} {{word:na4}}-{{light:ge4}}?"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:yao4}} {{word:hong2}}-{{word:se4}}-{{word:de}} {{word:hai2}}-{{word:shi4}} {{word:bai2}}-{{word:se4}}-{{word:de}}? (Do you want the red one or the white one?)"],ru:["{{Word:ni3}} {{word:yao4}} {{word:hong2}}-{{word:se4}}-{{word:de}} {{word:hai2}}-{{word:shi4}} {{word:bai2}}-{{word:se4}}-{{word:de}}?"],zh:[]}}]},{text:{en:["**A {{word:he2}} B** — A and B. Hé joins two nouns: nǐ hé wǒ, you and me. It joins nouns only, not whole sentences."],ru:["**A {{word:he2}} B** — Hé соединяет два существительных: nǐ hé wǒ — ты и я. Оно соединяет только существительные, а не целые предложения."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:he2}} {{word:wo3}}. (You and me.)"],ru:["{{Word:ni3}} {{word:he2}} {{word:wo3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:he2}} {{word:ta1}} {{word:qu4}} {{word:wai4}}-{{word:mian4}}. (He and I go outside.)"],ru:["{{Word:wo3}} {{word:he2}} {{word:ta1}} {{word:qu4}} {{word:wai4}}-{{word:mian4}}."],zh:[]}},{text:{en:["{{Word:liu4}}-{{light:ge4}} {{word:nan2}}-{{word:ren2}} {{word:he2}} {{word:qi1}}-{{light:ge4}} {{word:nv3}}-{{word:ren2}}. (Six men and seven women.)"],ru:["{{Word:liu4}}-{{light:ge4}} {{word:nan2}}-{{word:ren2}} {{word:he2}} {{word:qi1}}-{{light:ge4}} {{word:nv3}}-{{word:ren2}}."],zh:[]}}]},{text:{en:["**A + {{word:dui4}} + B + adjective** — A is that way toward B. Duì and a person before a describing word says how someone or something is toward them: tā duì wǒ hěn hǎo. Duì X lái shuō means for X."],ru:["**A + {{word:dui4}} + B + adjective** — Duì и человек перед описывающим словом говорят, каков кто-то или что-то по отношению к нему: tā duì wǒ hěn hǎo. Duì X lái shuō значит «для X»."],zh:[]},items:[{text:{en:["{{Word:ta1}} {{word:dui4}} {{word:wo3}} {{word:hen3}} {{word:hao3}}. (He's good to me.)"],ru:["{{Word:ta1}} {{word:dui4}} {{word:wo3}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:shui3}} {{word:dui4}} {{word:zhi2wu4}} {{word:hen3}} {{word:hao3}}. (Water is good for plants.)"],ru:["{{Word:shui3}} {{word:dui4}} {{word:zhi2wu4}} {{word:hen3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:dui4}} {{word:wo3}} {{word:lai2}} {{word:shuo1}}, {{word:zhe4}}-{{light:ge4}} {{word:hen3}} {{word:hao3}}. (For me, this is good.)"],ru:["{{Word:dui4}} {{word:wo3}} {{word:lai2}} {{word:shuo1}}, {{word:zhe4}}-{{light:ge4}} {{word:hen3}} {{word:hao3}}."],zh:[]}}]},{text:{en:["**{{word:dui4}} / {{word:bu4}} {{word:dui4}}** — Right / not right. Duì on its own says right: nǐ shuō-de duì, what you say is right. Bù duì is wrong; duì-bù-duì asks if it is right."],ru:["**{{word:dui4}} / {{word:bu4}} {{word:dui4}}** — Duì само по себе значит «верно»: nǐ shuō-de duì — то, что ты сказал, верно. Bù duì — неверно."],zh:[]},items:[{text:{en:["{{Word:ni3}} {{word:shuo1}} {{word:de}} {{word:dui4}}. (You're right.)"],ru:["{{Word:ni3}} {{word:shuo1}} {{word:de}} {{word:dui4}}."],zh:[]}},{text:{en:["{{Word:zhe4}} {{word:shi4}} {{word:bu4}} {{word:dui4}} {{word:de}} {{word:dong1xi}}. (This is a mistake.)"],ru:["{{Word:zhe4}} {{word:shi4}} {{word:bu4}} {{word:dui4}} {{word:de}} {{word:dong1xi}}."],zh:[]}},{text:{en:["{{Word:shui3}} {{word:dui4}} {{word:shen1ti3}} {{word:hao3}}. (Water is good for the body.)"],ru:["{{Word:shui3}} {{word:dui4}} {{word:shen1ti3}} {{word:hao3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 22 · Relationships 2 — Linking sentences"],zh:[],ru:["Урок 22 · Связи 2 — Как связать предложения"]},items:[{text:{en:["**{{word:yin1wei4}} + reason, result** — Because of the reason, the result. Yīnwèi starts the reason: yīnwèi it is cold, I am not going out. The reason can also come second, after a comma."],ru:["**{{word:yin1wei4}} + reason, result** — Yīnwèi начинает причину: yīnwèi холодно, я не иду на улицу. Причина может стоять и второй, после запятой."],zh:[]},items:[{text:{en:["{{Word:yin1wei4}} {{word:wo3}} {{word:hen3}} {{word:leng3}}, {{word:wo3}} {{word:bu4}} {{word:qu4}} {{word:wai4}}-{{word:mian4}}. (Because I'm cold, I'm not going outside.)"],ru:["{{Word:yin1wei4}} {{word:wo3}} {{word:hen3}} {{word:leng3}}, {{word:wo3}} {{word:bu4}} {{word:qu4}} {{word:wai4}}-{{word:mian4}}."],zh:[]}},{text:{en:["{{Word:yin1wei4}} {{word:hen3}} {{word:re4}}, {{word:wo3}} {{word:guan1}} {{word:le}} {{word:huo3}}. (Because it was hot, I turned off the fire.)"],ru:["{{Word:yin1wei4}} {{word:hen3}} {{word:re4}}, {{word:wo3}} {{word:guan1}} {{word:le}} {{word:huo3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:bu4}} {{word:chi1}}, {{word:yin1wei4}} {{word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}}. (I'm not eating, because I've finished.)"],ru:["{{Word:wo3}} {{word:bu4}} {{word:chi1}}, {{word:yin1wei4}} {{word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}}."],zh:[]}}]},{text:{en:["**sentence, {{word:dan4}}-{{word:shi4}} + sentence** — This, but that. Dàn-shì starts the second part and says but: it looks good, but it does not taste good."],ru:["**sentence, {{word:dan4}}-{{word:shi4}} + sentence** — Dàn-shì начинает вторую часть и значит «но»: выглядит хорошо, но на вкус нехорошо."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:yao4}} {{word:qu4}}, {{word:dan4}}-{{word:shi4}} {{word:wo3}} {{word:mei2}} {{word:you3}} {{word:jin1}}. (I want to go, but I have no money.)"],ru:["{{Word:wo3}} {{word:yao4}} {{word:qu4}}, {{word:dan4}}-{{word:shi4}} {{word:wo3}} {{word:mei2}} {{word:you3}} {{word:jin1}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:hen3}} {{word:xiao3}}, {{word:dan4}}-{{word:shi4}} {{word:hen3}} {{word:you3}} {{word:li4}}-{{word:qi4}}. (He's small, but very strong.)"],ru:["{{Word:ta1}} {{word:hen3}} {{word:xiao3}}, {{word:dan4}}-{{word:shi4}} {{word:hen3}} {{word:you3}} {{word:li4}}-{{word:qi4}}."],zh:[]}}]},{text:{en:["**{{word:ru2guo3}} X, the rest** — If X, then the rest. Rúguǒ starts the if-part, then a comma and the rest: rúguǒ you come, I'll wait for you."],ru:["**{{word:ru2guo3}} X, the rest** — Rúguǒ начинает часть «если», затем запятая и остальное: rúguǒ ты придёшь, я тебя подожду."],zh:[]},items:[{text:{en:["{{Word:ru2guo3}} {{word:ni3}} {{word:lai2}}, {{word:wo3}} {{word:deng3}} {{word:ni3}}. (If you come, I'll wait for you.)"],ru:["{{Word:ru2guo3}} {{word:ni3}} {{word:lai2}}, {{word:wo3}} {{word:deng3}} {{word:ni3}}."],zh:[]}},{text:{en:["{{Word:ru2guo3}} {{word:ni3}} {{word:bu4}} {{word:zhi1dao4}} {{word:zhe4}}-{{light:ge4}} {{word:ci2}}, {{word:wen4}} {{word:wo3}}. (If you don't know this word, ask me.)"],ru:["{{Word:ru2guo3}} {{word:ni3}} {{word:bu4}} {{word:zhi1dao4}} {{word:zhe4}}-{{light:ge4}} {{word:ci2}}, {{word:wen4}} {{word:wo3}}."],zh:[]}},{text:{en:["{{Word:ru2guo3}} {{word:ni3}} {{word:leng3}}, {{word:wo3}} {{word:gei3}} {{word:ni3}} {{word:yi1fu}}. (If you're cold, I'll give you clothes.)"],ru:["{{Word:ru2guo3}} {{word:ni3}} {{word:leng3}}, {{word:wo3}} {{word:gei3}} {{word:ni3}} {{word:yi1fu}}."],zh:[]}}]},{text:{en:["**(ru2guo3 X,) who + {{word:jiu4}} + verb** — (If X,) then who does the verb right away. Jiù goes right before the verb. After rúguǒ it means then; on its own it means right away or just: wǒ jiù qù, I'm going right away."],ru:["**(ru2guo3 X,) who + {{word:jiu4}} + verb** — Jiù стоит прямо перед глаголом. После rúguǒ оно значит «тогда»; само по себе — «сразу» или «только»: wǒ jiù qù — я иду сразу."],zh:[]},items:[{text:{en:["{{Word:ru2guo3}} {{word:ni3}} {{word:lai2}}, {{word:wo3}} {{word:jiu4}} {{word:deng3}} {{word:ni3}}. (If you come, I'll wait for you.)"],ru:["{{Word:ru2guo3}} {{word:ni3}} {{word:lai2}}, {{word:wo3}} {{word:jiu4}} {{word:deng3}} {{word:ni3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:xian4}}-{{word:zai4}} {{word:jiu4}} {{word:qu4}}. (I'm going right now.)"],ru:["{{Word:wo3}} {{word:xian4}}-{{word:zai4}} {{word:jiu4}} {{word:qu4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}} {{word:jiu4}} {{word:qu4}}. (I'll go as soon as I've eaten.)"],ru:["{{Word:wo3}} {{word:chi1}}-{{word:wan2}} {{word:le}} {{word:jiu4}} {{word:qu4}}."],zh:[]}}]},{text:{en:["**{{word:jiu4}} + number + counting word** — Only that many. Jiù before a number and counting word means only: wǒ jiù yī-gè, I have only one."],ru:["**{{word:jiu4}} + number + counting word** — Jiù перед числом и счётным словом значит «только»: wǒ jiù yī-gè — у меня только один."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:jiu4}} {{word:yi1}}-{{word:ge4}}. (I have only one.)"],ru:["{{Word:wo3}} {{word:jiu4}} {{word:yi1}}-{{word:ge4}}."],zh:[]}}]},{text:{en:["**{{word:yi1}} + verb + {{word:jiu4}} + verb** — As soon as one, the other. Yī, a verb, jiù and another verb says as soon as: yī kàn jiù zhīdào, you know as soon as you look."],ru:["**{{word:yi1}} + verb + {{word:jiu4}} + verb** — Yī, глагол, jiù и ещё глагол значат «как только»: yī kàn jiù zhīdào — как только посмотришь, поймёшь."],zh:[]},items:[{text:{en:["{{Word:na4}}-{{word:ge4}} {{word:yi1}} {{word:kan4}} {{word:jiu4}} {{word:zhi1dao4}}. (That is obvious.)"],ru:["{{Word:na4}}-{{word:ge4}} {{word:yi1}} {{word:kan4}} {{word:jiu4}} {{word:zhi1dao4}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 23 · Greetings"],zh:[],ru:["Урок 23 · Приветствия"]},items:[{text:{en:["**Name, sentence** — Someone, then what is said to them. Someone can be called or greeted first, then a comma and what is said: māma, wǒ huí lái le, Mom, I'm back; nǐ hǎo, nǐ shì xué-shēng ma, hello, are you a student?"],ru:["**Name, sentence** — Сначала можно позвать или поприветствовать, затем запятая и то, что говорят: māma, wǒ huí lái le — мама, я вернулся; nǐ hǎo, nǐ shì xué-shēng ma — здравствуйте, вы студент?"],zh:[]},items:[{text:{en:["{{Word:ma1ma}}, {{word:wo3}} {{word:hui2}} {{word:lai2}} {{word:le}}! (Mom, I'm back!)"],ru:["{{Word:ma1ma}}, {{word:wo3}} {{word:hui2}} {{word:lai2}} {{word:le}}!"],zh:[]}},{text:{en:["{{Word:ni3}} {{word:hao3}}, {{word:ni3}} {{word:shi4}} {{word:xue2}}-{{word:sheng1}} {{word:ma}}? (Hello, are you a student?)"],ru:["{{Word:ni3}} {{word:hao3}}, {{word:ni3}} {{word:shi4}} {{word:xue2}}-{{word:sheng1}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:na4}}, {{word:wo3}}-{{word:men}} {{word:zou3}}. (Well then, let us go.)"],ru:["{{Word:na4}}, {{word:wo3}}-{{word:men}} {{word:zou3}}."],zh:[]}}]},{text:{en:["**verb-verb** — Do the verb a little. Say a verb twice to do it a little or just try it. The second one is short and light: wǒ kàn-kan, let me have a look; xiè-xie, thanks."],ru:["**verb-verb** — Скажите глагол дважды, чтобы сделать это немного или попробовать. Второй слог короткий и лёгкий: wǒ kàn-kan — дай-ка посмотрю; xiè-xie — спасибо."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:kan4}}-{{light:kan4}}. (Let me have a look.)"],ru:["{{Word:wo3}} {{word:kan4}}-{{light:kan4}}."],zh:[]}},{text:{en:["{{Word:xie4}}-{{light:xie4}} {{word:ni3}}. (Thank you.)"],ru:["{{Word:xie4}}-{{light:xie4}} {{word:ni3}}."],zh:[]}},{text:{en:["{{Word:xie4}}-{{light:xie4}} {{word:ni3}} {{word:gei3}} {{word:wo3}} {{word:shui3}}. (Thank you for giving me water.)"],ru:["{{Word:xie4}}-{{light:xie4}} {{word:ni3}} {{word:gei3}} {{word:wo3}} {{word:shui3}}."],zh:[]}},{text:{en:["{{Word:xie4}}-{{light:xie4}}, {{word:wo3}} {{word:kan4}}-{{light:kan4}}. (Thanks, let me have a look.)"],ru:["{{Word:xie4}}-{{light:xie4}}, {{word:wo3}} {{word:kan4}}-{{light:kan4}}."],zh:[]}}]},{text:{en:["**{{word:mei2}} {{word:guan1xi}}** — Never mind. Méi guānxi says never mind: méi guānxi, wǒ bù pà, never mind, I am not afraid."],ru:["**{{word:mei2}} {{word:guan1xi}}** — Méi guānxi значит «ничего страшного»: méi guānxi, wǒ bù pà — ничего, я не боюсь."],zh:[]},items:[{text:{en:["{{Word:mei2}} {{word:guan1xi}}, {{word:wo3}} {{word:bu4}} {{word:pa4}}. (Never mind, I am not afraid.)"],ru:["{{Word:mei2}} {{word:guan1xi}}, {{word:wo3}} {{word:bu4}} {{word:pa4}}."],zh:[]}}]},{text:{en:['**Who + {{word:jiao4}} + "name"** — Who is called the name. Jiào and a name says what someone is called: wǒ jiào "Lisa", my name is Lisa. Nǐ jiào shénme? asks the name.'],ru:['**Who + {{word:jiao4}} + "name"** — Jiào и имя говорят, как кого-то зовут: wǒ jiào "Lisa" — меня зовут Лиза. Nǐ jiào shénme? спрашивает имя.'],zh:[]},items:[{text:{en:['{{Word:wo3}} {{word:jiao4}} "Lisa". (My name is Lisa.)'],ru:['{{Word:wo3}} {{word:jiao4}} "Lisa".'],zh:[]}},{text:{en:["{{Word:ni3}} {{word:jiao4}} {{word:shen2me}}? (What's your name?)"],ru:["{{Word:ni3}} {{word:jiao4}} {{word:shen2me}}?"],zh:[]}}]},{text:{en:["**{{word:bie2}} + verb!** — Don't do it! Bié before a verb says don't: bié pà, don't be afraid; bié zǒu, don't leave."],ru:["**{{word:bie2}} + verb!** — Bié перед глаголом значит «не надо»: bié pà — не бойся; bié zǒu — не уходи."],zh:[]},items:[{text:{en:["{{Word:bie2}} {{word:pa4}}! (Don't be afraid!)"],ru:["{{Word:bie2}} {{word:pa4}}!"],zh:[]}},{text:{en:["{{Word:bie2}} {{word:mo1}} {{word:huo3}}! (Don't touch the fire!)"],ru:["{{Word:bie2}} {{word:mo1}} {{word:huo3}}!"],zh:[]}},{text:{en:["{{Word:bie2}} {{word:dui4}} {{word:ta1}} {{word:shuo1}}! (Don't tell him!)"],ru:["{{Word:bie2}} {{word:dui4}} {{word:ta1}} {{word:shuo1}}!"],zh:[]}}]},{text:{en:["**verb! / {{word:bu4}} {{word:yao4}} + verb!** — Do it! / Don't do it! A verb on its own is an order: chī, eat! For don't, put bù yào first. A countdown ends on the order: yī, èr, sān, kāishǐ!"],ru:["**verb! / {{word:bu4}} {{word:yao4}} + verb!** — Глагол сам по себе — приказ: chī — ешь! Для «не надо» поставьте bù yào вперёд. Обратный отсчёт кончается приказом: yī, èr, sān, kāishǐ!"],zh:[]},items:[{text:{en:["{{Word:bu4}} {{word:yao4}} {{word:shuo1}}! (Don't talk!)"],ru:["{{Word:bu4}} {{word:yao4}} {{word:shuo1}}!"],zh:[]}},{text:{en:["{{Word:bu4}} {{word:yao4}} {{word:mo1}} {{word:wo3}}-{{word:de}} {{word:bi2zi}}! (Don't touch my nose!)"],ru:["{{Word:bu4}} {{word:yao4}} {{word:mo1}} {{word:wo3}}-{{word:de}} {{word:bi2zi}}!"],zh:[]}},{text:{en:["{{Word:yi1}}, {{word:er4}}, {{word:san1}}, {{word:kai1shi3}}! (One, two, three, go!)"],ru:["{{Word:yi1}}, {{word:er4}}, {{word:san1}}, {{word:kai1shi3}}!"],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 24 · Feelings"],zh:[],ru:["Урок 24 · Чувства"]},items:[{text:{en:["**Who {{word:jue2}}-{{word:de2}} + how / thought** — Who feels that. Jué-dé says feel or think, then how it is or a whole thought: wǒ jué-dé hǎo, I feel good; wǒ jué-dé wǒ néng, I think I can. Shuō and yào can take a person and hǎo too: wǒ shuō nǐ hǎo, I say hello."],ru:["**Who {{word:jue2}}-{{word:de2}} + how / thought** — Jué-dé говорит «чувствовать» или «думать», затем как оно или целая мысль: wǒ jué-dé hǎo — мне хорошо; wǒ jué-dé wǒ néng — я думаю, что смогу. Shuō и yào тоже берут человека и hǎo: wǒ shuō nǐ hǎo — я говорю «здравствуй»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:jue2}}-{{word:de2}} {{word:hao3}}. (I feel good.)"],ru:["{{Word:wo3}} {{word:jue2}}-{{word:de2}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:jue2}}-{{word:de2}} {{word:wo3}} {{word:neng2}}. (I think I can.)"],ru:["{{Word:wo3}} {{word:jue2}}-{{word:de2}} {{word:wo3}} {{word:neng2}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:shuo1}} {{word:ni3}} {{word:hao3}}. (I say hello.)"],ru:["{{Word:wo3}} {{word:shuo1}} {{word:ni3}} {{word:hao3}}."],zh:[]}},{text:{en:["{{Word:wo3}}-{{word:men}} {{word:hen3}} {{word:kai1}}-{{word:xin1}} {{word:ni3}} {{word:lai2}} {{word:le}}. (We're glad you've come.)"],ru:["{{Word:wo3}}-{{word:men}} {{word:hen3}} {{word:kai1}}-{{word:xin1}} {{word:ni3}} {{word:lai2}} {{word:le}}."],zh:[]}}]},{text:{en:["**feeling + what it is about** — Glad that it happened. A feeling can come first, with what it is about right after: hěn kāi-xīn nǐ lái le, I'm so glad you came."],ru:["**feeling + what it is about** — Чувство может стоять первым, а то, о чём оно, — сразу после него: hěn kāi-xīn nǐ lái le — я так рад, что ты пришёл."],zh:[]},items:[{text:{en:["{{Word:hen3}} {{word:kai1}}-{{word:xin1}} {{word:ni3}} {{word:lai2}} {{word:le}}! (I'm so glad you came!)"],ru:["{{Word:hen3}} {{word:kai1}}-{{word:xin1}} {{word:ni3}} {{word:lai2}} {{word:le}}!"],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 25 · Doubling Words"],zh:[],ru:["Урок 25 · Удвоение слов"]},items:[{text:{en:["**adjective-adjective-{{word:de}}** — Nice and … (stronger). Say a describing word twice, then -de, to make it stronger and livelier: yuán-yuán-de. No hěn is needed. Before a verb, hǎo-hǎo means well, properly."],ru:["**adjective-adjective-{{word:de}}** — Скажите описывающее слово дважды и добавьте -de, чтобы усилить его и оживить: yuán-yuán-de. Hěn не нужно. Перед глаголом hǎo-hǎo значит «как следует»."],zh:[]},items:[{text:{en:["{{Word:yue4}} {{word:yuan2}}-{{word:yuan2}}-{{word:de}}. (The moon is nice and round.)"],ru:["{{Word:yue4}} {{word:yuan2}}-{{word:yuan2}}-{{word:de}}."],zh:[]}},{text:{en:["{{Word:hao3}}-{{word:hao3}} {{word:xue2}}! (Study hard!)"],ru:["{{Word:hao3}}-{{word:hao3}} {{word:xue2}}!"],zh:[]}},{text:{en:["{{Word:xiao3}}-{{word:xiao3}}-{{word:de}} {{word:shui3}}-{{word:guo3}}. (A tiny fruit.)"],ru:["{{Word:xiao3}}-{{word:xiao3}}-{{word:de}} {{word:shui3}}-{{word:guo3}}."],zh:[]}}]},{text:{en:["**{{word:ge4}}-{{word:ge4}} / {{word:ren2}}-{{word:ren2}} + {{word:dou1}} + verb** — Every one does the verb. Say a counting word, or one of a few nouns, twice for every, and put dōu before the verb: rén-rén dōu, everyone; cì-cì dōu, every time."],ru:["**{{word:ge4}}-{{word:ge4}} / {{word:ren2}}-{{word:ren2}} + {{word:dou1}} + verb** — Скажите счётное слово или одно из немногих существительных дважды — получится «каждый»; dōu ставится перед глаголом: rén-rén dōu — все; cì-cì dōu — каждый раз."],zh:[]},items:[{text:{en:["{{Word:ren2}}-{{word:ren2}} {{word:dou1}} {{word:ai4}} {{word:ta1}}. (Everyone loves him.)"],ru:["{{Word:ren2}}-{{word:ren2}} {{word:dou1}} {{word:ai4}} {{word:ta1}}."],zh:[]}},{text:{en:["{{Word:ci4}}-{{word:ci4}} {{word:dou1}} {{word:yi1}}-{{word:yang4}}. (It's the same every time.)"],ru:["{{Word:ci4}}-{{word:ci4}} {{word:dou1}} {{word:yi1}}-{{word:yang4}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:tian1}}-{{word:tian1}} {{word:dou1}} {{word:he1}} {{word:shui3}}. (I drink water every day.)"],ru:["{{Word:wo3}} {{word:tian1}}-{{word:tian1}} {{word:dou1}} {{word:he1}} {{word:shui3}}."],zh:[]}}]}]},{type:"info",subtype:"grammar",title:{en:["Lesson 26 · Everyday Patterns"],zh:[],ru:["Урок 26 · Обороты на каждый день"]},items:[{text:{en:["**{{word:wo3}} {{word:lai2}} + verb** — Let me do the verb. Wǒ lái and a verb offers to do it: let me. On its own, wǒ lái! means let me!"],ru:["**{{word:wo3}} {{word:lai2}} + verb** — Wǒ lái и глагол — предложение сделать самому: давай я. Само по себе wǒ lái! значит «давай я!»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:lai2}} {{word:na2}}. (Let me carry it.)"],ru:["{{Word:wo3}} {{word:lai2}} {{word:na2}}."],zh:[]}},{text:{en:["{{Word:wo3}} {{word:lai2}} {{word:kan4}}. (Let me look.)"],ru:["{{Word:wo3}} {{word:lai2}} {{word:kan4}}."],zh:[]}}]},{text:{en:["**{{word:gei3}} {{word:wo3}} + verb + {{word:yi1}}-{{word:xia4}}** — Let me do it for a moment. Gěi wǒ and a verb asks for a turn: let me do it. Yī-xià after the verb makes it a quick try."],ru:["**{{word:gei3}} {{word:wo3}} + verb + {{word:yi1}}-{{word:xia4}}** — Gěi wǒ и глагол просят очередь: дай мне это сделать. Yī-xià после глагола делает это быстрой попыткой."],zh:[]},items:[{text:{en:["{{Word:gei3}} {{word:wo3}} {{word:kan4}} {{word:yi1}}-{{word:xia4}}. (Let me take a look.)"],ru:["{{Word:gei3}} {{word:wo3}} {{word:kan4}} {{word:yi1}}-{{word:xia4}}."],zh:[]}},{text:{en:["{{Word:gei3}} {{word:wo3}} {{word:ting1}}-{{light:ting1}}. (Let me hear it.)"],ru:["{{Word:gei3}} {{word:wo3}} {{word:ting1}}-{{light:ting1}}."],zh:[]}}]},{text:{en:["**Who + {{word:bang1}} + person + verb** — Who helps the person do it. Bāng, the person, then the verb: help someone do it. Bāng, the person, then xué and the verb is teach: you help them learn. Hěn huì says someone is good at it."],ru:["**Who + {{word:bang1}} + person + verb** — Bāng, человек, затем глагол — помочь кому-то это сделать. Bāng, человек, затем xué и глагол — учить: вы помогаете ему учиться. Hěn huì говорит, что кто-то хорошо это умеет."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:bang1}} {{word:ni3}} {{word:na2}}. (I help you carry it.)"],ru:["{{Word:wo3}} {{word:bang1}} {{word:ni3}} {{word:na2}}."],zh:[]}},{text:{en:["{{Word:ni3}} {{word:bang1}} {{word:wo3}} {{word:xue2}} {{word:xie3}}. (You help me learn to write.)"],ru:["{{Word:ni3}} {{word:bang1}} {{word:wo3}} {{word:xue2}} {{word:xie3}}."],zh:[]}},{text:{en:["{{Word:ta1}} {{word:hen3}} {{word:hui4}} {{word:bang1}} {{word:ren2}} {{word:xue2}}. (He's a good teacher.)"],ru:["{{Word:ta1}} {{word:hen3}} {{word:hui4}} {{word:bang1}} {{word:ren2}} {{word:xue2}}."],zh:[]}}]},{text:{en:["**Who + {{word:jiao4}} + person + verb** — Who has the person do it. Jiào, someone, then a verb: tell or have them do it. It works like ràng; bù ràng says you won't let them."],ru:["**Who + {{word:jiao4}} + person + verb** — Jiào, кто-то, затем глагол: велеть или попросить их сделать это. Работает как ràng; bù ràng — «не разрешать»."],zh:[]},items:[{text:{en:["{{Word:wo3}} {{word:jiao4}} {{word:ta1}}-{{word:men}} {{word:deng3}}. (I told them to wait.)"],ru:["{{Word:wo3}} {{word:jiao4}} {{word:ta1}}-{{word:men}} {{word:deng3}}."],zh:[]}},{text:{en:["{{Word:jiao4}} {{word:ta1}} {{word:shuo1}}-{{word:xia4}}-{{word:qu4}}. (Have him keep talking.)"],ru:["{{Word:jiao4}} {{word:ta1}} {{word:shuo1}}-{{word:xia4}}-{{word:qu4}}."],zh:[]}}]},{text:{en:["**…, {{word:hao3}} {{word:ma}}?** — …, okay? Hǎo ma at the end, after a comma, makes a suggestion or asks nicely: wǒ-men chū-qù wánr, hǎo ma? Hǎo on its own says okay."],ru:["**…, {{word:hao3}} {{word:ma}}?** — Hǎo ma в конце, после запятой, делает предложение или вежливую просьбу: wǒ-men chū-qù wánr, hǎo ma? Hǎo само по себе значит «хорошо»."],zh:[]},items:[{text:{en:["{{Word:wo3}}-{{word:men}} {{word:chu1}}-{{word:qu4}} {{word:wan2r}}, {{word:hao3}} {{word:ma}}? (Let's go out and play, okay?)"],ru:["{{Word:wo3}}-{{word:men}} {{word:chu1}}-{{word:qu4}} {{word:wan2r}}, {{word:hao3}} {{word:ma}}?"],zh:[]}},{text:{en:["{{Word:hao3}}! (Okay!)"],ru:["{{Word:hao3}}!"],zh:[]}},{text:{en:["{{Word:hao3}}, {{word:wo3}} {{word:xian4}}-{{word:zai4}} {{word:jiu4}} {{word:lai2}}. (Okay, I'm coming right now.)"],ru:["{{Word:hao3}}, {{word:wo3}} {{word:xian4}}-{{word:zai4}} {{word:jiu4}} {{word:lai2}}."],zh:[]}}]},{text:{en:["**{{word:xia4}} + thing** — The thing falls. Xià before a thing can mean falls: xià shuǐ, it rains."],ru:["**{{word:xia4}} + thing** — Xià перед вещью может значить «падает»: xià shuǐ — идёт дождь."],zh:[]},items:[{text:{en:["{{Word:tian1}}-{{word:shang4}} {{word:xia4}} {{word:shui3}} {{word:le}}. (It's raining.)"],ru:["{{Word:tian1}}-{{word:shang4}} {{word:xia4}} {{word:shui3}} {{word:le}}."],zh:[]}}]}]}];export{r as default,o as meta};
